(function(){
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(w,origin)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const Q=(id,senseId,errorType,prompt,answer,d1,d2,explain)=>({id,senseId,type:'辨義與用法',errorType,prompt,options:[answer,d1,d2],answer,explain});
const P=(w,origin,contexts,mistakes,quiz)=>D(w,{etymology:E(w,origin),contexts,mistakes,quiz});
P('twelfth','From Old English twelfta, the ordinal form of twelve.',[C('twelfth.s1','序数','The twelfth chapter introduces the character who changes the course of the story.','第十二章介紹了改變故事走向的角色。','the twelfth + singular count noun','Ordinal adjective: number 12 in a series.','The chapter occupies position twelve.'),C('twelfth.s2','分数','Only a twelfth of the orchard was damaged by the late frost.','晚霜只損害了果園的十二分之一。','one twelfth of + whole','Fraction: one of twelve equal parts.','The damaged area is one equal part out of twelve.')],[M('The twelfth chapter was the first chapter, before chapters one through eleven.','The twelfth chapter came after the first eleven chapters.','Twelfth marks position twelve, not position one.')],[Q('twelfth.q1','twelfth.s1','meaning','Which chapter is the twelfth chapter?','The chapter in position number 12.','The chapter in position number 2.','One of twelve equal pieces of a chapter.','The ordinal sense gives the position in a series.'),Q('twelfth.q2','twelfth.s2','context','If a twelfth of the orchard was damaged, what fraction was affected?','One of twelve equal parts.','Twelve whole orchards.','One of two equal parts.','A twelfth is one part when a whole is divided into twelve.'),Q('twelfth.q3','twelfth.s1','distinction','Which use is ordinal rather than fractional?','She finished in twelfth place.','She received a twelfth of the prize.','One twelfth of the land was wet.','“Twelfth place” names a position in an order.'),Q('twelfth.q4','twelfth.s2','grammar','Choose the correct fraction phrase.','one twelfth of the orchard','the twelfth orchard of twelve equal land','twelfth of twelve orchards in position','“One twelfth of” expresses a single part of a whole.')]);
P('twelve','From Old English twelf, a Germanic numeral for the number after eleven.',[C('twelve.s1','数字','The box contains twelve coloured pencils, one for each student at the table.','盒子裡有十二支彩色鉛筆，桌邊每位學生一支。','twelve + plural count noun','Cardinal number: the number after eleven.','There are twelve individual pencils.')],[M('The box contains twelve pencil, one for each of the twelve students.','The box contains twelve pencils, one for each of the twelve students.','Twelve before a count noun requires the plural form “pencils.”','grammar')],[Q('twelve.q1','twelve.s1','meaning','How many pencils are in the box?','Twelve.','Eleven.','Twenty.','Twelve is the number immediately after eleven.'),Q('twelve.q2','twelve.s1','context','If twelve students each receive one pencil, how many pencils are needed?','Twelve pencils.','Two pencils.','Twenty pencils.','One for each of twelve students requires twelve.'),Q('twelve.q3','twelve.s1','grammar','Choose the grammatically correct phrase.','twelve coloured pencils','twelve coloured pencil','twelve twelfth pencils','A plural count noun follows the number twelve.'),Q('twelve.q4','twelve.s1','distinction','Which quantity equals twelve?','Six pairs of gloves.','Five pairs of gloves.','Seven pairs of gloves.','Six pairs contain twelve individual gloves.')]);
P('twelvemonth','A compound of twelve + month, an old-fashioned or dialect word for a period of twelve months.',[C('twelvemonth.s1','时间','The lease was renewed for a twelvemonth after the tenant agreed to stay.','租客同意續租後，租約延長了一年。','for a twelvemonth','Noun: a period of twelve months.','The lease covers a full year.')],[M('The lease ran for a twelvemonth, which ended after only four weeks.','The lease ran for a twelvemonth, covering twelve months.','A twelvemonth is twelve months, not four weeks.')],[Q('twelvemonth.q1','twelvemonth.s1','meaning','How long is a twelvemonth?','Twelve months.','Twelve days.','Four weeks.','The compound names a period of a full year.'),Q('twelvemonth.q2','twelvemonth.s1','context','A lease lasts a twelvemonth. When does it end?','After twelve months.','After twelve hours.','After two years.','The old-fashioned noun means a twelve-month period.'),Q('twelvemonth.q3','twelvemonth.s1','distinction','Which phrase is closest in meaning to twelvemonth?','a year','a fortnight','a decade','A year contains twelve months.'),Q('twelvemonth.q4','twelvemonth.s1','register','Where might you encounter twelvemonth?','In old-fashioned or dialect speech.','Only as a modern technical term for a day.','As a synonym for a century.','The source labels the word old-fashioned or dialect.')]);
P('twentieth','From twenty + ordinal suffix -th, naming position 20 or one of twenty equal parts.',[C('twentieth.s1','序数','The twentieth runner crossed the line just before the rain began.','第二十名跑者在開始下雨前越過終點線。','the twentieth + item in a series','Ordinal: number 20 in a series.','The runner occupies position twenty.'),C('twentieth.s2','分数','One twentieth of the donation paid for the laboratory’s safety equipment.','這筆捐款的二十分之一用來購買實驗室安全設備。','one twentieth of + whole','Fraction: one of twenty equal parts.','The amount is one equal share out of twenty.')],[M('The twentieth runner finished first, ahead of all nineteen runners who started earlier.','The twentieth runner finished after the first nineteen runners.','Twentieth is position twenty, after the first nineteen.')],[Q('twentieth.q1','twentieth.s1','meaning','Which runner is the twentieth?','The runner in position number 20.','The runner in position number 2.','One of twenty equal shares.','The ordinal sense marks a position in a series.'),Q('twentieth.q2','twentieth.s2','context','What is one twentieth of a donation?','One of twenty equal portions of it.','Twenty full donations.','One of two equal portions.','A twentieth is a fraction with twenty equal parts.'),Q('twentieth.q3','twentieth.s1','distinction','Which phrase uses the ordinal sense?','the twentieth anniversary','one twentieth of the budget','a twentieth share of the funds','An anniversary in position 20 uses the ordinal.'),Q('twentieth.q4','twentieth.s2','grammar','Complete the fraction: “She donated ___ of her savings.”','one twentieth','the twentieth position','twenty twentieths of each savings','“One twentieth of” expresses one equal part out of twenty.')]);
P('twenty','From Old English twentig, a Germanic numeral meaning two tens.',[C('twenty.s1','数字','The museum hired twenty guides for the opening weekend.','博物館在開幕週末聘用了二十名導覽員。','twenty + plural count noun','Cardinal number: the number equal to two times ten.','The museum employs two groups of ten guides.')],[M('The museum hired twenty guide for the opening weekend.','The museum hired twenty guides for the opening weekend.','The cardinal number twenty takes a plural count noun.','grammar')],[Q('twenty.q1','twenty.s1','meaning','What number is equal to two tens?','Twenty.','Twelve.','Thirty.','Twenty is two groups of ten.'),Q('twenty.q2','twenty.s1','context','How many guides did the museum hire?','Twenty guides.','Two guides.','Twelve guides.','The sentence states that two tens of guides were hired.'),Q('twenty.q3','twenty.s1','grammar','Choose the correct phrase.','twenty visitors','twenty visitor','twentieth visitors','A cardinal number before a count noun takes a plural noun.'),Q('twenty.q4','twenty.s1','distinction','Which quantity is twenty?','Four groups of five books.','Four groups of four books.','Two groups of six books.','Four fives make twenty.')]);
P('twenty-five cents','A fixed money phrase for 25 cents, one quarter of a US dollar.',[C('twenty-five cents.s1','货币','The bus fare was twenty-five cents, so Omar paid with a quarter.','公車票價是二十五美分，所以奧馬爾付了一枚二角五分硬幣。','cost / pay twenty-five cents','Noun phrase: a coin or amount worth 25 cents, one fourth of a dollar.','A US quarter is worth twenty-five cents.')],[M('The ticket cost twenty-five cents, so she paid one full dollar exactly.','The ticket cost twenty-five cents, so she paid with a quarter-dollar coin.','Twenty-five cents is one quarter of a dollar, not a full dollar.')],[Q('twenty-five cents.q1','twenty-five cents.s1','meaning','How much is twenty-five cents in US currency?','One quarter of a dollar.','One whole dollar.','One tenth of a dollar.','Twenty-five cents is one fourth of a dollar.'),Q('twenty-five cents.q2','twenty-five cents.s1','context','Which coin can pay a twenty-five-cent bus fare exactly?','A US quarter.','A ten-dollar bill only.','A five-cent nickel only.','A quarter is worth twenty-five cents.'),Q('twenty-five cents.q3','twenty-five cents.s1','distinction','Which price equals twenty-five cents?','One quarter of a dollar.','Five quarters of a dollar.','One hundred cents.','Twenty-five is a quarter of one hundred cents.'),Q('twenty-five cents.q4','twenty-five cents.s1','word-choice','Choose the correct sentence.','The ride costs twenty-five cents.','The ride costs twenty-five centses.','The ride costs twenty-five cent dollar.','The fixed phrase names an amount of money worth 25 cents.')]);
P('twice','From Old English twiges, an adverb meaning on two occasions or two times as much.',[C('twice.s1','次数','I checked the address twice before sending the parcel.','寄出包裹前，我把地址檢查了兩次。','do something twice','Adverb: on two occasions.','The checking happened two separate times.'),C('twice.s2','倍数','The new storage room is twice as large as the old one.','新的儲藏室是舊儲藏室的兩倍大。','twice as + adjective + as','Adverb: double in amount or degree.','Its size is two times the old room’s size.')],[M('I checked the address twice, meaning I checked it exactly three separate times.','I checked the address twice, meaning I checked it on two occasions.','Twice means two occasions, not three.')],[Q('twice.q1','twice.s1','meaning','If the label was checked twice, how many checks were made?','Two checks.','Three checks.','One check.','The occasion sense means two separate times.'),Q('twice.q2','twice.s2','context','A room is twice as large as another. What is its relative size?','Double the other room’s size.','Half the other room’s size.','Exactly the same size.','“Twice as large” expresses a factor of two.'),Q('twice.q3','twice.s1','distinction','Which sentence uses twice for occasions?','She visited the archive twice last week.','The archive is twice as large.','The archive holds double the books.','The first describes two visits.'),Q('twice.q4','twice.s2','grammar','Choose the standard comparison.','twice as long as the original','twice longer than the original in every context','twice long the original','“Twice as + adjective + as” expresses double the amount.')]);
P('twig','The branch noun is from Old English twigge, a small branch; the verbs meaning understand or notice have uncertain histories.',[C('twig.s1','植物','A dry twig snapped under the hiker’s boot.','乾枯的小樹枝在健行者的靴子下折斷了。','a twig from / on + tree','Noun: a small thin branch growing from a larger branch.','The twig is a thin branch from the tree.'),C('twig.s2','突然明白','It took Leo a moment to twig why the lights had gone out.','利奧過了一會兒才明白燈為什麼熄了。','twig what / why + clause (chiefly British)','Verb: suddenly understand something.','He reaches an understanding after a short delay.'),C('twig.s3','察觉','Mara twigged that the supposedly empty room was still occupied.','瑪拉突然察覺那間號稱空著的房間仍有人。','twig that + clause','Verb: notice or realize something suddenly.','She notices the hidden fact.')],[M('Leo twigged why the lights failed, but he remained completely unaware of the reason.','Leo twigged why the lights failed and suddenly understood the reason.','Twig as a verb means suddenly understand or notice.')],[Q('twig.q1','twig.s1','meaning','What is a twig on a tree?','A small, thin branch.','A whole tree trunk.','A type of coin worth a quarter-dollar.','The noun names a small branch growing from a larger one.'),Q('twig.q2','twig.s2','context','What happened when Leo twigged why the lights went out?','He suddenly understood the reason.','He snapped a branch underfoot.','He switched the lights on twice.','The chiefly British verb can mean suddenly understand.'),Q('twig.q3','twig.s3','distinction','Mara twigged that the room was occupied. What did she do?','She suddenly noticed or realized it.','She broke a small branch.','She counted twelve people.','The clause expresses a newly noticed fact.'),Q('twig.q4','twig.s1','word-choice','Which use is the plant-related noun?','A bird carried a twig to its nest.','I twigged what the sign meant.','She twigged that someone was waiting.','The bird carries a small branch.')]);
P('twilight','From Middle English twi- + light; twi- likely means “half,” though its exact connotation is uncertain.',[C('twilight.s1','黄昏','The hikers reached the cabin in the soft twilight after sunset.','日落後，健行者在柔和的暮光中抵達小屋。','in the twilight / at twilight','Noun: soft light after sunset and before night.','The sky still has a little light after the sun has set.'),C('twilight.s2','衰退末期','The newspaper closed during the twilight of its influence in the city.','這家報紙在其影響力逐漸衰退的末期停刊。','the twilight of + career / era / power','Noun: the final stage of something as its importance fades.','The paper is nearing the end of its influence.')],[M('They walked in the twilight at noon, when the sun was high and the sky was fully bright.','They walked in the twilight just after sunset, as daylight faded.','Twilight is the dim light after sunset, not bright midday.')],[Q('twilight.q1','twilight.s1','meaning','When is twilight in the evening sense?','After sunset while some soft light remains.','At noon under a high sun.','Before dawn when the sun is already high.','The literal sense is the fading light between sunset and night.'),Q('twilight.q2','twilight.s2','context','What is the twilight of a newspaper’s influence?','The final period as its importance declines.','The moment it first becomes popular.','A daily time when the office turns off its lights.','The figurative sense describes a fading final stage.'),Q('twilight.q3','twilight.s1','distinction','Which use describes the sky’s light?','The fields were silver in the twilight.','The club was in the twilight of its success.','The twilight of her career lasted a decade.','The fields are lit by dusk light.'),Q('twilight.q4','twilight.s2','word-choice','Which phrase uses twilight figuratively?','the twilight of the empire','the twilight sky after sunset','a walk in the evening twilight','The empire is in its fading final stage.')]);
P('twin','From Old English twinn, “double,” used for one of two children born together and for paired similar things.',[C('twin.s1','兄弟姐妹','The twins were born minutes apart, and one has a brother of the same age.','這對雙胞胎只相差幾分鐘出生，其中一人有一個同齡的兄弟。','a twin brother / sister','Noun: one of two children born to the same mother at the same time.','The children are twins born in the same birth.'),C('twin.s2','成对事物','The hotel’s twin rooms each contain two separate single beds.','旅館的雙床房各有兩張分開的單人床。','twin + similar paired objects','Adjective: two similar things that form a pair.','The two beds make a paired room type.')],[M('The twins were born ten years apart to different mothers at different times.','The twins were born to the same mother at the same time.','Twins are two children born to the same mother at the same time.')],[Q('twin.q1','twin.s1','meaning','Who is a person’s twin?','One of two children born to the same mother at the same time.','A child born ten years later to another mother.','A room with two beds.','The sibling sense refers to children sharing one birth.'),Q('twin.q2','twin.s2','context','What does a twin room contain in this example?','Two separate single beds forming a pair.','One large bed only.','Two children born to the same mother.','Twin describes two similar items paired together.'),Q('twin.q3','twin.s1','distinction','Which phrase refers to a sibling?','her twin brother','a twin bedroom','twin beds','The brother is one of the children born at the same time.'),Q('twin.q4','twin.s2','word-choice','Which use is adjectival?','The hotel booked us a twin room.','She has a twin sister.','Her twin was born first.','Twin modifies room to mean a paired room type.')]);
P('twine','From Old English twīn, “double thread,” related to twisting strands together.',[C('twine.s1','绳线','He tied the parcel with twine instead of plastic tape.','他用細繩而不是塑膠膠帶綁好包裹。','tie / bind something with twine','Noun: strong fine thread made by twisting strands together.','The cord is made from twisted strands.'),C('twine.s2','缠绕','The ivy began to twine around the old iron gate.','常春藤開始纏繞在舊鐵門上。','twine around / through + object','Verb: twist or wind around something.','The plant curls around the gate.')],[M('He tied the parcel with twine made from a single smooth sheet of metal.','He tied the parcel with strong fine twine made from twisted fibres.','Twine is fine cord made by twisting strands, not a solid metal sheet.')],[Q('twine.q1','twine.s1','meaning','What is twine used for on the parcel?','A strong fine cord for tying it.','A metal sheet to cover it.','A soft light in the evening sky.','Twine is thread made by twisting strands together.'),Q('twine.q2','twine.s2','context','What did the ivy do around the gate?','It wound and curled around it.','It tied the gate with a parcel string.','It changed the gate into a different material.','The verb means twist or wind around something.'),Q('twine.q3','twine.s1','distinction','Which sentence uses twine as a noun?','She cut a length of twine to tie the box.','The vine twined around the post.','The stems twine around one another.','A length of cord is the noun sense.'),Q('twine.q4','twine.s2','grammar','Which sentence uses twine as a verb?','The young plant twined around the fence.','A spool of twine lay on the table.','She bought twine for the package.','“Twined around” describes winding around an object.')]);
P('twinkle','Recorded in Middle English for a light that flickers; the deeper origin is uncertain.',[C('twinkle.s1','闪烁','The distant stars twinkle more clearly on a cold, cloudless night.','在寒冷無雲的夜晚，遠處的星星閃爍得更清楚。','a light / star twinkles','Verb: shine with brightness that changes quickly.' ,'The stars repeatedly brighten and dim.'),C('twinkle.s2','眼神','His eyes twinkled with amusement when the children told their joke.','孩子們講笑話時，他的眼睛因覺得有趣而閃亮。','eyes twinkle with + emotion','Verb: eyes shine with joy or amusement.' ,'The expression in his eyes shows amusement.'),C('twinkle.s3','微光','A tiny twinkle appeared on the horizon as the lighthouse turned.','燈塔轉動時，地平線上出現一點微光。','a twinkle of + light','Noun: a tiny light that keeps changing brightness.','The visible point of light flashes briefly.')],[M('The stars twinkled steadily with no change in brightness throughout the entire night.','The stars twinkled with brightness that kept changing in the clear night sky.','To twinkle is to shine with quickly changing brightness.')],[Q('twinkle.q1','twinkle.s1','meaning','How do stars twinkle?','Their brightness changes quickly as they shine.','They remain completely dark.','They rotate like a dancer on a stage.','The light sense involves repeated changes in brightness.'),Q('twinkle.q2','twinkle.s2','context','What did his twinkling eyes suggest?','He felt amused by the children’s joke.','He was unable to see any light.','He was in the twilight of his career.','Eyes can twinkle to show joy or amusement.'),Q('twinkle.q3','twinkle.s3','distinction','Which phrase uses twinkle as a noun?','a twinkle of light on the horizon','the stars twinkle above us','her eyes twinkle with joy','The first names a tiny changing light.'),Q('twinkle.q4','twinkle.s1','word-choice','Which sentence describes a changing light?','The signal lamp began to twinkle through the fog.','The lamp stayed steadily dark.','The lamp wound around the pole.','The lamp flashes with changing brightness.')]);
P('twinkling','From twinkle + -ing; the noun phrase “in the twinkling of an eye” means in an instant.',[C('twinkling.s1','闪烁与瞬间','In the twinkling of an eye, the stage lights went out and the scene changed.','轉眼之間，舞台燈光熄滅，場景也隨之改變。','in the twinkling of an eye','Adjective: sparkling with unsteady light; as a noun in the idiom, an instant.','The idiom emphasizes that the change happened extremely quickly.')],[M('The scene changed in the twinkling of an eye, meaning the change took several full days.','The scene changed in the twinkling of an eye, meaning it changed almost instantly.','The idiom means in an instant, not over several days.')],[Q('twinkling.q1','twinkling.s1','meaning','What does “in the twinkling of an eye” mean?','In an instant.','After several weeks.','Twice on separate occasions.','The idiom describes an extremely short time.'),Q('twinkling.q2','twinkling.s1','context','How quickly did the stage scene change?','Almost instantly.','It took all month.','It changed only after the play ended.','The phrase emphasizes immediate change.'),Q('twinkling.q3','twinkling.s1','distinction','Which use refers to light rather than a brief time?','twinkling lights reflected in the pond','the scene changed in a twinkling','the answer came in the twinkling of an eye','The lights themselves sparkle with unsteady brightness.'),Q('twinkling.q4','twinkling.s1','word-choice','Which sentence uses the idiom correctly?','The bird vanished in the twinkling of an eye.','The repair took in the twinkling of an eye for three months.','The twinkling of an eye is a twelve-month period.','The idiom means the bird disappeared almost immediately.')]);
P('twirl','Of uncertain origin; proposed connections include Old English þwirl, “churn handle,” and Old Norse þvara, “stirrer.”',[C('twirl.s1','舞蹈动作','The dancer twirled across the stage beneath the spotlight.','舞者在聚光燈下旋轉著穿過舞台。','twirl around / across + place','Verb: move or dance in circles with a light, rapid turning motion.','The dancer spins while moving across the stage.'),C('twirl.s2','手指转动','She twirled a pencil between her fingers while waiting for the call.','她等電話時用手指轉著一支鉛筆。','twirl + object between / around fingers','Verb: make something turn round and round.','The pencil rotates repeatedly in her fingers.')],[M('The dancer twirled across the stage by walking straight without any turn or rotation.','The dancer twirled across the stage with light, rapid turns.','Twirl describes turning in circles, not moving straight without rotation.')],[Q('twirl.q1','twirl.s1','meaning','What did the dancer do when she twirled?','Turned rapidly in circles while moving.','Walked straight without turning.','Twisted someone’s words.','The movement sense is a light, rapid circular turn.'),Q('twirl.q2','twirl.s2','context','How did she twirl the pencil?','She made it turn repeatedly between her fingers.','She used it to write a transcript.','She broke it into twelve equal pieces.','The object sense means make something spin round and round.'),Q('twirl.q3','twirl.s1','distinction','Which sentence uses twirl for a person’s movement?','The child twirled in the living room.','She twirled the pencil between two fingers.','He twisted the lid open.','A child circling while moving shows the movement sense.'),Q('twirl.q4','twirl.s2','word-choice','Which phrase uses twirl with an object?','twirl a ribbon around a stick','twirl across the dance floor','twirl in a circle','The ribbon is made to rotate around the stick.')]);
P('twist','From Old English twist, “a cord or something twisted,” later also the act of turning or distorting.',[C('twist.s1','旋转','Twist the jar lid firmly to open the sealed container.','用力轉動罐蓋，打開密封容器。','twist + object to turn or wind it','Verb: turn something so that it bends or winds around.' ,'The lid is rotated to loosen it.'),C('twist.s2','歪曲意思','The article twisted the witness’s words to suggest the opposite meaning.','文章歪曲了證人的話，使其看起來像是在表達相反意思。','twist someone’s words / meaning','Verb: force something out of its natural shape or meaning.','The report distorts what the witness said.'),C('twist.s3','轉折','The mystery takes an unexpected twist near the end.','這個懸疑故事接近結尾時出現了意想不到的轉折。','an unexpected twist','Noun: a turn or an unexpected change.','The plot changes in a surprising way.')],[M('The article quoted her words accurately and fairly, but the editor said it twisted what she had said.','The article altered her words to imply something she had not meant.','Twisting someone’s words means distorting their meaning.')],[Q('twist.q1','twist.s1','meaning','How should you twist the jar lid?','Turn it so the sealed lid loosens.','Leave it fixed without turning.','Change its meaning in a newspaper.','The physical verb means turn or wind something.'),Q('twist.q2','twist.s2','context','What did the article do to the witness’s words?','Distorted them to imply a different meaning.','Quoted them exactly and fairly.','Turned them into a physical rope.','The figurative verb means force words away from their intended meaning.'),Q('twist.q3','twist.s3','distinction','What is an unexpected twist in a mystery?','A surprising change in the story’s direction.','A jar lid turned by hand.','A sentence copied word for word.','The noun can mean an unexpected turn or change.'),Q('twist.q4','twist.s1','word-choice','Which sentence uses twist for physical turning?','Twist the wire into a small loop.','The report twisted the witness’s meaning.','The novel had a final twist.','Bending the wire into a loop is a physical action.')]);
P('twister','From twist + -er; the storm sense names violently rotating winds.',[C('twister.s1','天气','A twister damaged several barns before moving across the open fields.','龍捲風掃過空曠田野前，摧毀了幾座穀倉。','a twister (informal for tornado)','Noun: a violent storm with very strong winds turning rapidly in a circle.','The storm’s winds rotate violently.'),C('twister.s2','制作绳线','The rope maker used a small twister to twist fibres into a strong cord.','製繩工使用小型捻線機，把纖維擰成結實的繩索。','a twister for rope / wire','Noun: a person or device that twists rope, wire, or thread into shape.','The tool turns fibres together to form cord.')],[M('The weather report called a calm cloudless afternoon a twister despite there being no rotating storm.','The weather report warned that a twister with rotating winds was approaching.','A weather twister is a violent rotating-wind storm, not calm weather.')],[Q('twister.q1','twister.s1','meaning','What is a twister in a weather report?','A violent storm with rapidly rotating winds.','A machine used to twist rope fibres.','A small branch from a tree.','The storm sense is an informal term for a tornado.'),Q('twister.q2','twister.s2','context','What did the rope maker’s twister do?','Twisted fibres together to make cord.','Carried a trainload of goods.','Measured the wind without turning anything.','The tool sense is a device that twists material into shape.'),Q('twister.q3','twister.s1','distinction','Which sentence uses twister for a storm?','The twister tore the roof from the barn.','The twister coiled the fibres into rope.','The twister turned wire into loops in the workshop.','The roof damage is caused by a rotating storm.'),Q('twister.q4','twister.s2','word-choice','Which phrase refers to the rope-making device?','a twister that coils strands into cord','a twister crossing the open plain','a twister warning issued by the weather service','The device coils fibres together.')]);
P('two','From Old English twā, a Germanic numeral for the number after one.',[C('two.s1','数字','The visitor bought two tickets for the evening performance.','訪客買了兩張晚場演出的票。','two + plural count noun','Cardinal number: the number after one.','There are exactly two tickets.')],[M('The visitor bought two ticket for the evening performance.','The visitor bought two tickets for the evening performance.','Two before a count noun takes its plural form.','grammar')],[Q('two.q1','two.s1','meaning','How many tickets did the visitor buy?','Two.','One.','Twelve.','Two is the number immediately after one.'),Q('two.q2','two.s1','context','How many people can use two tickets if each uses one?','Two people.','One person only.','Twenty people.','Each of the two tickets admits one person.'),Q('two.q3','two.s1','grammar','Choose the correct phrase.','two tickets','two ticket','twoth tickets','The count noun is plural after two.'),Q('two.q4','two.s1','distinction','Which group contains two objects?','A pair of shoes.','A single shoe.','Three separate shoes.','A pair consists of two items.')]);
P('two times','The phrase two + times, equivalent to twice when counting separate occasions.',[C('two times.s1','次数','The machine scans each parcel two times before it leaves the depot.','每件包裹離開貨運站前，機器都會掃描兩次。','do something two times','Adverbial phrase: on two separate occasions; same meaning as twice.','The scan is repeated once, making two occasions in all.')],[M('The machine scanned each parcel two times, meaning it scanned each parcel three times.','The machine scanned each parcel two times, meaning it scanned it on two occasions.','Two times counts two occasions, not three.')],[Q('two times.q1','two times.s1','meaning','How often does the machine scan a parcel two times?','On two separate occasions.','On three occasions.','Only once.','The phrase is equivalent to twice.'),Q('two times.q2','two times.s1','context','If a label is checked two times, how many checks are made?','Two checks.','Twenty checks.','One check.','Each check is one occasion, so there are two.'),Q('two times.q3','two times.s1','distinction','Which sentence uses two times for repeated occasions?','She called the office two times before noon.','The office is two times larger.','Two times ten equals twenty.','The first describes two separate calls.'),Q('two times.q4','two times.s1','word-choice','Choose the sentence that matches two times.','The alarm sounded two times during the test.','The alarm sounded twelve times during the test.','The alarm never sounded.','Two times means the event occurred on two occasions.')]);
P('two weeks','A phrase for a period of fourteen days, also called a fortnight.',[C('two weeks.s1','时间','The repair shop said the replacement part would arrive in two weeks.','修理店說替換零件會在兩週後送到。','in / for two weeks','Noun phrase: a period of fourteen days.','The expected wait is fourteen days.')],[M('The repair shop said the part would arrive in two weeks, meaning tomorrow.','The repair shop said the part would arrive in two weeks, meaning after fourteen days.','Two weeks is a fourteen-day period, not one day.')],[Q('two weeks.q1','two weeks.s1','meaning','How many days are in two weeks?','Fourteen days.','Seven days.','Twenty days.','Two weeks equals fourteen days.'),Q('two weeks.q2','two weeks.s1','context','If a part arrives in two weeks, how long must the shop wait?','Fourteen days.','Two hours.','A full year.','The phrase sets a fourteen-day wait.'),Q('two weeks.q3','two weeks.s1','distinction','Which phrase means the same length of time as two weeks?','a fortnight','a twelvemonth','a twentieth','A fortnight is fourteen days.'),Q('two weeks.q4','two weeks.s1','word-choice','Which sentence uses two weeks as a duration?','The clinic will review the results in two weeks.','The clinic will review them two times.','The clinic is twenty weeks old.','“In two weeks” indicates the review occurs after fourteen days.')]);
P('twofold','From two + -fold, meaning either twice as much or consisting of two parts.',[C('twofold.s1','倍数','The new filter produced a twofold increase in clean water output.','新濾芯使潔淨水產量增加到原來的兩倍。','a twofold increase / rise','Adjective: two times as much or as many.','The amount is multiplied by two.'),C('twofold.s2','两方面','The proposal has a twofold purpose: reduce waste and lower costs.','這項提案有雙重目的：減少浪費並降低成本。','a twofold purpose / task','Adjective: made up of two separate parts or aspects.','The proposal contains two distinct aims.')],[M('The proposal was described as twofold but listed five unrelated objectives.','The proposal was twofold, with two aims: reducing waste and lowering costs.','Twofold can mean having two parts or aspects, not five.')],[Q('twofold.q1','twofold.s1','meaning','What does a twofold increase in output mean?','Output becomes twice as much.','Output falls to half.','Output stays unchanged.','The numerical sense means two times as much.'),Q('twofold.q2','twofold.s2','context','Why is the proposal’s purpose called twofold?','It has two separate aims.','It has one aim repeated twice.','It has five unrelated aims.','Twofold can mean made up of two parts.'),Q('twofold.q3','twofold.s1','distinction','Which phrase uses the amount sense?','a twofold rise in production','a twofold purpose with two aims','a twofold plan with two sections','The rise in production indicates a quantity doubled.'),Q('twofold.q4','twofold.s2','word-choice','Which phrase uses the “two aspects” sense?','a twofold responsibility for safety and training','a twofold increase in visitors','a twofold fall in costs','The responsibility has two distinct parts.')]);
P('tycoon','From Japanese taikun, “great lord,” brought into English through 19th-century political usage.',[C('tycoon.s1','商业人物','A shipping tycoon funded the restoration of the city’s historic docks.','一位航運大亨資助了該市歷史碼頭的修復。','a business / media / shipping tycoon','Noun: a wealthy and influential person in business or industry.','The business owner has substantial wealth and influence.')],[M('The shipping tycoon had no wealth, influence, or business interests of any kind.','The shipping tycoon was wealthy and influential in the industry.','A tycoon is a wealthy and influential business or industry figure.')],[Q('tycoon.q1','tycoon.s1','meaning','Why might a shipping executive be called a tycoon?','The person is wealthy and influential in the industry.','The person is learning a first job.','The person types letters for a living.','Tycoon refers to a powerful, wealthy business figure.'),Q('tycoon.q2','tycoon.s1','context','What did the shipping tycoon do for the old docks?','Funded their restoration.','Turned them into a typewriter.','Sent a twister across the harbour.','The sentence portrays a powerful industry figure with resources.'),Q('tycoon.q3','tycoon.s1','distinction','Which person is most likely a tycoon?','An influential owner of a major media company.','A new typist at a small office.','A passenger waiting for a bus.','A major company owner fits the wealthy influential sense.'),Q('tycoon.q4','tycoon.s1','word-choice','Which phrase is natural?','a technology tycoon with major investments','a tycoon who has no money or influence','a tycoon meaning a small branch','The first phrase describes a wealthy influential business figure.')]);
P('type','From Greek typos, “impression, form, or model,” via Latin typus.',[C('type.s1','类别','This type of soil drains quickly but holds enough moisture for vegetables.','這種類型的土壤排水快，又能為蔬菜保留足夠水分。','a type of + category or thing','Noun: a group of people or things with shared features.','The soil belongs to a category with common properties.'),C('type.s2','键盘输入','Please type your full name into the form before submitting it.','提交表格前，請在欄位中輸入你的全名。','type + text on a keyboard','Verb: write using a keyboard.','The name is entered by pressing keys.')],[M('Please type your name into the form by speaking it aloud without using a keyboard.','Please type your name into the form using the keyboard.','Type as a verb means write using a keyboard, not merely speak.')],[Q('type.q1','type.s1','meaning','What does “this type of soil” refer to?','A category of soil with shared characteristics.','A name entered on a keyboard.','A person employed to type documents.','The noun sense is a group sharing features.'),Q('type.q2','type.s2','context','What should you do to enter your name in the form?','Write it using the keyboard.','Choose a category of soil.','Print a whole book by hand.','The verb means write with a keyboard.'),Q('type.q3','type.s1','distinction','Which sentence uses type as a noun?','Which type of music does the café play?','Type your answer in the box.','She typed a short note.','The first asks about a category.'),Q('type.q4','type.s2','grammar','Which phrase uses type as a verb?','Type the code into the login field.','A type of code is required.','This type appears often.','The instruction uses type as an action performed on a keyboard.')]);
P('typecast','A compound of type + cast; the acting sense assigns a role based on a performer’s familiar image.',[C('typecast.s1','演员选角','After several detective roles, the actor was typecast as a police inspector.','演過幾個偵探角色後，這名演員總被固定選為警探。','be typecast as + role','Verb: choose an actor for a role of a kind they often play.','The casting repeats the actor’s established screen image.'),C('typecast.s2','固定分类','The report typecast the neighbourhood as dangerous and ignored its varied communities.','報告把這個社區固定歸類為危險之地，忽略了其中多元的群體。','typecast someone / something as + category','Verb: put someone or something in one fixed category, ignoring other qualities.','The label reduces a complex place to one stereotype.')],[M('The report typecast the district as unsafe after carefully describing its many different communities and conditions.','The report typecast the district as unsafe and ignored evidence of its diversity.','Typecast means reduce someone or something to a fixed category, not represent all its complexity.')],[Q('typecast.q1','typecast.s1','meaning','Why was the actor typecast as a detective?','Casting directors kept choosing the familiar kind of role.','The actor typed every line on a keyboard.','The actor refused all acting roles.','The acting sense repeats a role matching the actor’s usual image.'),Q('typecast.q2','typecast.s2','context','How did the report typecast the neighbourhood?','It put the complex area into one fixed category.','It listed every resident’s address by hand.','It cast actors for a film about the district.','The broader sense is to impose a fixed label and ignore other traits.'),Q('typecast.q3','typecast.s1','distinction','Which sentence uses the acting sense?','She was typecast as a stern head teacher in every drama.','Critics typecast the town as dull.','The data typecast the whole group as one category.','The first refers to assigning an actor a repeated sort of role.'),Q('typecast.q4','typecast.s2','word-choice','Which use criticizes a stereotype?','The survey typecast all rural residents as resistant to change.','The director typecast him as the captain again.','The actor was typecast in another comedy.','The survey reduces a diverse group to one assumption.')]);
P('typescript','A compound of type + script, a document typed on a machine or keyboard.',[C('typescript.s1','文稿','The editor requested a clean typescript of the report before the final layout.','編輯要求在最後排版前提供一份整潔的打字稿。','a typescript of + document','Noun: a copy of a document or book that has been typed.','The report exists as a typed manuscript before final publication.')],[M('The editor requested a typescript written entirely by hand in ink.','The editor requested a typescript prepared by typing the report.','A typescript is typed, not handwritten.')],[Q('typescript.q1','typescript.s1','meaning','What is a typescript of a report?','A copy prepared by typing the document.','A handwritten painting of the report.','A category of reports with shared topics.','The word names a typed copy of a text.'),Q('typescript.q2','typescript.s1','context','Why did the editor need the typescript before layout?','It was the clean typed copy to prepare for publication.','It was a type of printing ink.','It was a storm warning from the coast.','The typescript is a typed manuscript used before final publication.'),Q('typescript.q3','typescript.s1','distinction','Which item is a typescript?','A typed manuscript of a novel.','A handwritten note never entered on a keyboard.','A machine that prints keys onto paper.','The manuscript has been typed.'),Q('typescript.q4','typescript.s1','word-choice','Choose the natural phrase.','submit a clean typescript of the article','submit a typescript by speaking the article aloud','submit a typescript that is only a type of font','A typescript is a typed copy of the article.')]);
P('typewriter','A compound of type + writer, naming a machine that prints letters when keys are pressed.',[C('typewriter.s1','办公设备','Her grandfather still writes letters on a manual typewriter.','她的祖父仍用手動打字機寫信。','write / type a letter on a typewriter','Noun: a machine that prints letters on paper when its keys are pressed.','The machine makes printed characters as the writer presses keys.')],[M('He composed the letter on a typewriter without pressing keys or putting any letters on paper.','He composed the letter on a typewriter by pressing keys that printed letters on paper.','A typewriter produces characters when its keys are pressed.')],[Q('typewriter.q1','typewriter.s1','meaning','What does a typewriter do when its keys are pressed?','Prints letters directly onto paper.','Displays a storm map on a screen only.','Automatically changes one word category into another.','A typewriter is a keyed machine that prints letters on paper.'),Q('typewriter.q2','typewriter.s1','context','How did her grandfather write the letter?','He used a manual machine with keys that printed letters.','He dictated it to a twister.','He sent it as a twenty-five-cent coin.','The sentence uses typewriter for the mechanical writing device.'),Q('typewriter.q3','typewriter.s1','distinction','Which object is a typewriter?','A machine with keys that strike letters onto a page.','A document copy that has already been typed.','An employee hired to type documents.','The machine itself is a typewriter.'),Q('typewriter.q4','typewriter.s1','word-choice','Which phrase is natural?','feed paper into the typewriter','feed a typewriter into the transcript','typewriter the machine by hand','Paper is placed in the machine to receive printed letters.')]);
P('typhoon','English typhoon reflects Greek Typhon and Portuguese tufão from Arabic, Persian, or Hindi tufan; Cantonese tai fung may also have influenced its form or sense.',[C('typhoon.s1','天气','The typhoon forced fishing boats to remain in the harbour overnight.','颱風迫使漁船在港口停留了一夜。','a typhoon strikes / approaches','Noun: a violent storm with extremely strong winds forming over a tropical sea.','The tropical cyclone brings dangerous winds.')],[M('The forecast called the calm inland breeze a typhoon even though no tropical storm or strong wind existed.','The forecast warned that a typhoon with violent winds was approaching the coast.','A typhoon is a powerful tropical storm, not a calm inland breeze.')],[Q('typhoon.q1','typhoon.s1','meaning','Where does a typhoon form according to this entry?','Over a tropical sea.','Inside a quiet inland garden.','On a typewriter ribbon.','A typhoon is a violent storm forming over tropical seas.'),Q('typhoon.q2','typhoon.s1','context','Why did the fishing boats stay in harbour?','A dangerous typhoon was approaching.','They were being typecast in a film.','A twinkling light had appeared.','The strong tropical storm made sailing unsafe.'),Q('typhoon.q3','typhoon.s1','distinction','Which forecast describes a typhoon?','A tropical storm with extremely strong rotating winds.','A light shower with no wind over a dry inland plain.','A small branch falling in a garden.','The first has the intensity and location of the storm sense.'),Q('typhoon.q4','typhoon.s1','word-choice','Which phrase is natural?','the typhoon damaged homes along the coast','the typhoon typed a report on paper','the typhoon means a calm clear morning','A typhoon can cause serious wind damage.')]);
P('typical','From Greek typikos, “of a type,” from typos “form or pattern.”',[C('typical.s1','典型特征','Dry summers are typical of this region’s climate.','乾燥的夏季是這個地區氣候的典型特徵。','typical of + group or place','Adjective: having the usual features of a group or person.','The climate shows a usual regional pattern.'),C('typical.s2','习惯行为','Typical! He borrowed my charger and returned it with the cable missing.','真是老樣子！他借走我的充電器，還回來時卻少了線。','Typical! + familiar behavior','Exclamation: used when someone behaves in their usual annoying way.','The speaker complains that the behavior is familiar and frustrating.')],[M('Dry summers are typical of the region even though they have never occurred there.','Dry summers are typical of the region because they occur there regularly.','Typical features are usual for a group; a never-occurring event is not typical.')],[Q('typical.q1','typical.s1','meaning','What does it mean that dry summers are typical of a region?','They are usual features of its climate.','They have never occurred there.','They happen only once in a century.','The adjective describes usual group or regional features.'),Q('typical.q2','typical.s2','context','Why does the speaker say “Typical!” after the charger is returned without its cable?','The person has repeated a familiar annoying habit.','The person has done something completely unexpected and welcome.','The charger is a common type of device.','The exclamation signals familiar frustrating behavior.'),Q('typical.q3','typical.s1','distinction','Which phrase uses typical descriptively?','a typical winter for the northern coast','Typical! He has misplaced the keys again.','typical of his annoying habit','The first describes the usual features of a season.'),Q('typical.q4','typical.s2','word-choice','Which response uses the exclamation sense?','Typical! She is late again.','This flower is typical of the region.','That is a typical shape for the species.','The exclamation comments on familiar annoying behavior.')]);
P('typically','From typical + -ly, forming an adverb meaning in the usual manner or usually.',[C('typically.s1','通常情况','Typically, the clinic closes at five, except on public holidays.','通常診所下午五點關門，公眾假期除外。','typically + clause / typically do something','Adverb: in the normal way for a person, group, or situation; usually.','The closing time is the normal pattern.')],[M('Typically, the clinic always closes at five with no exception, including holidays, although it often stays open.','Typically, the clinic closes at five, though it may vary on holidays.','Typically means usually or in a normal pattern; it does not guarantee no exceptions.')],[Q('typically.q1','typically.s1','meaning','What does typically mean in the clinic example?','Usually or in the normal pattern.','Never, under any circumstances.','In a way that is completely unusual.','The adverb indicates what normally happens.'),Q('typically.q2','typically.s1','context','If the clinic typically closes at five, what should a visitor expect?','Five is the usual closing time, though exceptions may occur.','It is guaranteed to close at exactly five every day.','It never closes.','Typically gives the normal pattern without promising no exceptions.'),Q('typically.q3','typically.s1','distinction','Which sentence uses typically as an adverb?','Typically, buses run every twenty minutes here.','The typical bus is blue.','A typical route has six stops.','Typically modifies the statement about what usually happens.'),Q('typically.q4','typically.s1','word-choice','Choose a natural use.','The shop typically opens later on Sundays.','The shop is typically the usual adjective of a shop.','Typically, the shop is an unusual exception every day.','The adverb introduces the shop’s usual Sunday pattern.')]);
P('typify','From type + -ify, meaning to make or serve as a representative example of a type.',[C('typify.s1','代表特征','Narrow lanes and stone wells typify the historic quarter.','狹窄巷道和石井是這個歷史街區的典型特徵。','features typify + group / period','Verb: represent the usual qualities of a class or period.','The features are characteristic of the quarter.')],[M('Narrow lanes typify the historic quarter, although no narrow lane exists there.','Narrow lanes typify the historic quarter because they are characteristic of it.','To typify a place, a feature must represent its usual qualities.')],[Q('typify.q1','typify.s1','meaning','What do narrow lanes do in the sentence?','Represent characteristic features of the historic quarter.','Type names into a computer form.','Turn the quarter into a storm.','Typify means represent the usual qualities of something.'),Q('typify.q2','typify.s1','context','Why do stone wells typify the old town?','They are characteristic features of it.','They are found nowhere in the town.','They are a typewriter used by residents.','The features serve as representative examples.'),Q('typify.q3','typify.s1','distinction','Which sentence uses typify correctly?','Long dry summers typify the region.','The region typifies the report by typing it.','The region is typify by its climate.','The climate pattern represents the region’s usual qualities.'),Q('typify.q4','typify.s1','grammar','Choose the correct subject for typify.','Stone bridges typify the old village.','Stone bridges is typify the old village.','The old village typifying by stone bridges.','A plural subject can take typify to introduce characteristic features.')]);
P('typist','From type + -ist, naming someone whose work is typing documents.',[C('typist.s1','职业','The typist prepared the meeting minutes before the director arrived.','主任到達前，打字員已準備好會議紀錄。','a typist prepares / types + document','Noun: someone employed to type documents.','The worker enters the minutes using a keyboard.')],[M('The typist prepared the minutes by never using a keyboard or entering any text.','The typist prepared the minutes by typing them on a keyboard.','A typist is employed to type documents.')],[Q('typist.q1','typist.s1','meaning','What does a typist do at work?','Types documents using a keyboard.','Repairs tyres on cars.','Decides the outcome of a sports match.','The occupation centers on typing documents.'),Q('typist.q2','typist.s1','context','What did the typist prepare before the director arrived?','The typed meeting minutes.','A storm over the tropical sea.','A type of soil.','Meeting minutes are a document a typist can prepare.'),Q('typist.q3','typist.s1','distinction','Which person is a typist?','An employee who enters letters into documents.','A person who decides whether a ball is out.','A person who writes a music score by hand only.','The first person is employed to type.'),Q('typist.q4','typist.s1','word-choice','Which phrase is natural?','hire a typist to prepare the report','hire a typist to umpire a tennis final','hire a typist to be the type of report','A typist can be hired to produce typed documents.')]);
P('typo','Shortened form of typographical error, an error introduced in typing or typesetting.',[C('typo.s1','文字错误','A typo changed “public” to a different word in the printed notice.','排版錯誤把印刷通知中的「public」變成了另一個詞。','a typo in + text / report','Noun: an error in typing or typesetting, such as a wrong letter.','A wrong letter changes the intended word.')],[M('The proofreader called the correct spelling of “public” a typo even though no letter was wrong.','The proofreader corrected a typo that changed one letter in “public.”','A typo is an actual typing or typesetting error, not a correct spelling.')],[Q('typo.q1','typo.s1','meaning','What is a typo?','A typing or typesetting error, such as a wrong letter.','A person paid to type documents.','A complete category of words.','The noun means an error introduced while typing or setting text.'),Q('typo.q2','typo.s1','context','What happened in the printed notice?','A wrong letter changed the intended word.','The notice was turned into a storm.','The typewriter grew a branch.','The wrong letter is a typographical error.'),Q('typo.q3','typo.s1','distinction','Which is a typo?','A missing letter in a printed address.','A deliberate choice of a different font.','A correctly spelled word in the right context.','The missing letter is an unintended text error.'),Q('typo.q4','typo.s1','word-choice','Which phrase is natural?','spot a typo in the final paragraph','hire a typo to prepare a letter','twice a typo means an error on two occasions','A typo can be spotted and corrected in text.')]);
P('typographical','From typographic + -al; typographic ultimately combines Greek typos “impression” and graphein “write.”',[C('typographical.s1','排版与字体','The designer fixed a typographical error in the page number and adjusted the font spacing.','設計師修正了頁碼中的排版錯誤，並調整字體間距。','typographical + error / feature / layout','Adjective: concerned with type, fonts, and the layout of printed or digital text.','The error and spacing concern the presentation of text.')],[M('The reviewer called the argument typographical because it concerned the speaker’s personal motives rather than fonts or layout.','The reviewer called the page-number error typographical because it concerned the printed text.','Typographical relates to type, fonts, or text layout, not motives.')],[Q('typographical.q1','typographical.s1','meaning','What does a typographical error concern?','The type, fonts, or layout of text.','A person’s secret motive.','A tropical storm over the sea.','The adjective relates to how text is set or presented.'),Q('typographical.q2','typographical.s1','context','Why was the page-number problem typographical?','It was an error in the printed text layout.','It changed the author’s personal motive.','It made the page twice as long.','A wrong page number is an error in typeset material.'),Q('typographical.q3','typographical.s1','distinction','Which issue is typographical?','Uneven spacing between letters in a heading.','A character’s motivation in a novel.','A region’s usual summer weather.','Letter spacing concerns the appearance and layout of text.'),Q('typographical.q4','typographical.s1','word-choice','Choose the natural phrase.','a typographical error in the printed table','a typographical motive for the decision','a typographical typhoon warning over the sea','The printed-table error concerns text layout.')]);
P('tyrannical','From tyrant + -ical, ultimately Greek tyrannos, “absolute ruler.”',[C('tyrannical.s1','专制统治','The tyrannical ruler imprisoned critics and used power without regard for their rights.','這位暴虐的統治者囚禁批評者，行使權力時完全不顧他們的權利。','a tyrannical ruler / regime','Adjective: using power in a cruel and unfair way.','The ruler treats people cruelly and unjustly.'),C('tyrannical.s2','不容异议','Her tyrannical supervisor rejected every suggestion and allowed no disagreement.','她專橫的主管拒絕所有建議，不容許任何異議。','a tyrannical boss / supervisor','Adjective: behaving like a boss who allows no disagreement.','The supervisor insists on control and will not hear other views.')],[M('The tyrannical supervisor welcomed disagreement and treated every worker’s view fairly.','The tyrannical supervisor rejected disagreement and treated workers unfairly.','Tyrannical describes cruel unfair use of power or refusal to permit disagreement.')],[Q('tyrannical.q1','tyrannical.s1','meaning','Why was the ruler tyrannical?','He used power cruelly and unfairly.','He invited criticism and protected rights.','He typed official documents.','The first sense involves cruel, unjust use of power.'),Q('tyrannical.q2','tyrannical.s2','context','What made the supervisor tyrannical?','She allowed no disagreement with her decisions.','She asked workers to offer suggestions.','She shared every decision equally.','The workplace sense describes an overbearing boss.'),Q('tyrannical.q3','tyrannical.s1','distinction','Which example is tyrannical rule?','A leader imprisons peaceful critics and ignores their rights.','A manager invites feedback before deciding.','A team votes on a shared plan.','The first uses power cruelly and unfairly.'),Q('tyrannical.q4','tyrannical.s2','word-choice','Which sentence uses the boss-related sense?','The tyrannical boss would not let anyone question her orders.','The tyrannical empire imprisoned political opponents.','The tyrannical storm crossed the tropical sea.','The first sentence describes a boss who tolerates no disagreement.')]);
P('tyre','British spelling of tire for the rubber cover around a wheel; the word’s deeper history is uncertain.',[C('tyre.s1','车辆零件','The mechanic replaced the front tyre after finding a nail in it.','技師發現前輪輪胎裡有釘子後，把輪胎換掉了。','a car / bicycle tyre','Noun: a thick rubber cover around a wheel.','The tyre surrounds the wheel and needs replacement after damage.')],[M('The mechanic replaced the tyre, a thin metal handle attached to the steering wheel.','The mechanic replaced the tyre, the thick rubber cover around the wheel.','A tyre is the rubber cover around a wheel, not a steering handle.')],[Q('tyre.q1','tyre.s1','meaning','What is a tyre?','A thick rubber cover around a wheel.','A metal handle used to steer.','A machine that prints letters.','The noun names the rubber covering fitted around a wheel.'),Q('tyre.q2','tyre.s1','context','Why did the mechanic replace the front tyre?','A nail had damaged the rubber cover.','The driver had typed the wrong word.','The car had changed its type.','A puncture can damage a tyre.'),Q('tyre.q3','tyre.s1','distinction','Which spelling is standard in British English?','tyre','tyer','tire only','British English normally writes the wheel covering as tyre.'),Q('tyre.q4','tyre.s1','word-choice','Which phrase is natural?','inflate the bicycle tyre','type the bicycle tyre on a keyboard','transmit the tyre into a wheel','A tyre can be inflated when fitted to a wheel.')]);
P('u-boat','From German U-Boot, shortened from Unterseeboot, literally “undersea boat.”',[C('u-boat.s1','海战','The convoy changed course after a U-boat was reported off the coast.','沿岸傳來德國潛艇出沒的報告後，船隊改變了航向。','a German U-boat','Noun: a submarine used by the German navy, especially in the two world wars.','The vessel is a German naval submarine.')],[M('The historian identified the surfaced passenger ferry as a German U-boat even though it was not a submarine or naval vessel.','The historian identified the German navy’s submerged vessel as a U-boat.','A U-boat is a German naval submarine, not an ordinary passenger ferry.')],[Q('u-boat.q1','u-boat.s1','meaning','What is a U-boat?','A submarine used by the German navy.','A German typewriter.','A passenger tram in a harbour.','The historical term names a German naval submarine.'),Q('u-boat.q2','u-boat.s1','context','Why did the convoy change course?','A German submarine had been reported nearby.','A typist had corrected a typo.','A twin room was unavailable.','A U-boat was a military threat to ships.'),Q('u-boat.q3','u-boat.s1','distinction','Which vessel is a U-boat?','A German navy submarine from a world war.','A civilian ferry carrying tourists.','A cargo transporter with no military role.','The German military submarine matches the source sense.'),Q('u-boat.q4','u-boat.s1','word-choice','Which phrase is historically accurate?','a German U-boat submerged off the coast','a U-boat hired to type a report','a U-boat meaning a rubber wheel cover','A U-boat is a submarine used by the German navy.')]);
P('ubiquitous','From Latin ubique, “everywhere,” + -ous.',[C('ubiquitous.s1','普遍存在','Smartphones are now ubiquitous in the city, appearing in nearly every hand.','如今智慧型手機在城裡隨處可見，幾乎人人手上都有。','ubiquitous + object / technology','Adjective: seeming to be present everywhere at the same time.','The phones appear in nearly every part of city life.'),C('ubiquitous.s2','广泛分布','Ubiquitous cameras cover most entrances across the hospital campus.','醫院園區大多數入口都廣泛設有攝影機。','ubiquitous throughout / across + area','Adjective: spread widely through an area or group.','The cameras occur throughout the campus, not literally at every place in the world.')],[M('Cameras were called ubiquitous throughout the campus even though only one was installed at a single entrance.','Cameras were ubiquitous throughout the campus, with units installed at most entrances.','Ubiquitous means present everywhere or spread widely, not confined to one spot.')],[Q('ubiquitous.q1','ubiquitous.s1','meaning','What does it mean that smartphones are ubiquitous in the city?','They seem to be present everywhere in city life.','Only one person owns a phone.','They have disappeared from public spaces.','The first sense emphasizes seeming presence everywhere.'),Q('ubiquitous.q2','ubiquitous.s2','context','How are the cameras distributed across the campus?','They are spread widely among most entrances.','One camera is fixed at a single door.','They are found only in a different city.','This sense means widely spread through an area.'),Q('ubiquitous.q3','ubiquitous.s1','distinction','Which phrase uses the everywhere sense?','ubiquitous mobile phones in modern life','ubiquitous cameras across a particular campus','a ubiquitous species spread across one forest','The phrase describes a technology that seems to be everywhere.'),Q('ubiquitous.q4','ubiquitous.s2','word-choice','Which phrase focuses on broad distribution in one area?','ubiquitous cameras throughout the hospital','ubiquitous phones seeming to be everywhere','ubiquitous as a word in every language','The cameras are widely spread throughout a defined area.')]);
P('ugly','From Old Norse uggligr, “dreadful or frightening,” later extended to appearance and moral character.',[C('ugly.s1','外观','The old stain left an ugly mark on the otherwise clean wall.','舊污漬在原本乾淨的牆上留下了一道難看的痕跡。','an ugly + appearance or object','Adjective: unpleasant to see because the shape, colour, or features look harsh.','The mark spoils the wall’s appearance.'),C('ugly.s2','危险局势','An ugly quarrel broke out when the meeting became increasingly hostile.','會議氣氛愈來愈敵對，最後爆發了一場危險的爭吵。','an ugly fight / quarrel / situation','Adjective: threatening or likely to become violent or dangerous.','The argument risks escalating into violence.'),C('ugly.s3','道德厌恶','The investigation revealed the ugly truth about the company’s treatment of workers.','調查揭露了公司對待員工的令人厭惡的真相。','the ugly truth / side of + conduct','Adjective: morally unpleasant or causing disgust.','The conduct is ethically repellent.')],[M('The ugly dispute was harmless and peaceful, with no hostility or danger at all.','The ugly dispute became hostile and threatened to turn violent.','Ugly can describe a dangerous or threatening situation, not only an unpleasant appearance.')],[Q('ugly.q1','ugly.s1','meaning','Why was the mark on the wall called ugly?','Its appearance was unpleasant and harsh.','It threatened to become violent.','It revealed a moral scandal.','The first sense describes something unpleasant to see.'),Q('ugly.q2','ugly.s2','context','What does an ugly quarrel suggest?','A hostile argument likely to become dangerous.','A visually unattractive wall stain.','A pleasant disagreement with no tension.','The second sense concerns a threatening or potentially violent situation.'),Q('ugly.q3','ugly.s3','distinction','What is the ugly truth about the company?','A morally disgusting fact about its conduct.','A stain on a wall.','A quarrel that may become violent.','The moral sense describes conduct that causes disgust.'),Q('ugly.q4','ugly.s1','word-choice','Which use is about visual appearance?','an ugly scar on the painted door','an ugly quarrel at the meeting','the ugly truth about the contract','The scar is unpleasant to look at.')]);
P('ulcer','From Latin ulcus, “sore or ulcer,” through medical usage.',[C('ulcer.s1','健康','The doctor examined a slow-healing ulcer on the patient’s lower leg.','醫生檢查了病人小腿上一處癒合緩慢的潰瘍。','a skin / stomach ulcer','Noun: a painful damaged area on skin or an internal lining that heals slowly.','The sore is damaged tissue that has not healed quickly.')],[M('The doctor called the healthy, painless skin with no damaged tissue an ulcer.','The doctor diagnosed a painful, slow-healing area of damaged skin as an ulcer.','An ulcer is a damaged area of skin or lining, often painful and slow to heal.')],[Q('ulcer.q1','ulcer.s1','meaning','What is an ulcer?','A damaged, often painful area on skin or an internal lining.','A healthy area of skin with no injury.','A tiny branch growing from a tree.','The medical noun names a sore that may heal slowly.'),Q('ulcer.q2','ulcer.s1','context','Why was the leg examined?','It had a slow-healing damaged area.','It had a typographical error.','It was wrapped in a twin bed.','A persistent sore may be an ulcer.'),Q('ulcer.q3','ulcer.s1','distinction','Which condition is an ulcer?','A painful sore on the stomach lining.','A healthy unmarked skin surface.','A bruise that vanished immediately with no tissue damage.','The sore on an internal lining fits the definition.'),Q('ulcer.q4','ulcer.s1','word-choice','Which phrase is natural?','treat a stomach ulcer','type an ulcer on a keyboard','an ulcer of a typewriter key','A stomach ulcer is a damaged area in the stomach lining.')]);
P('ulterior','From Latin ulterior, “farther or more distant,” the comparative of ultra “beyond.”',[C('ulterior.s1','隐藏动机','She suspected an ulterior motive behind the unusually generous offer.','她懷疑這個異常慷慨的提議背後另有隱情。','an ulterior motive / purpose','Adjective: an unadmitted or secret reason for an action.','The apparent kindness may conceal another purpose.')],[M('His ulterior motive was openly announced and was the only reason he gave for helping.','His ulterior motive was concealed behind his apparently generous offer.','An ulterior motive is not admitted openly; it is a hidden reason.')],[Q('ulterior.q1','ulterior.s1','meaning','What is an ulterior motive?','A hidden reason for doing something.','The final announced purpose with no hidden aim.','A usual feature shared by a group.','The adjective describes a secret reason beyond the admitted one.'),Q('ulterior.q2','ulterior.s1','context','Why did she suspect an ulterior motive?','The generous offer might conceal a different purpose.','The offer was clearly described as a secret reason.','She had already typed the contract.','A motive can be ulterior when its real purpose is hidden.'),Q('ulterior.q3','ulterior.s1','distinction','Which action suggests an ulterior motive?','He offers help but secretly expects control in return.','She explains every reason for helping openly.','They agree to help with no hidden goal.','A concealed expectation is a secret reason.'),Q('ulterior.q4','ulterior.s1','word-choice','Which phrase is natural?','suspect an ulterior motive behind the donation','an ulterior tyre around the wheel','an ulterior fraction of the grant','The collocation “ulterior motive” means a hidden purpose.')]);
P('ultimate','From Latin ultimatus, “last,” from ultimus, superlative of ultra “beyond.”',[C('ultimate.s1','最终目标','The ultimate goal of the programme is to make clean water available to every village.','這項計畫的最終目標是讓每個村莊都能取得潔淨水。','the ultimate aim / result','Adjective: coming at the end of a long process.','The goal is the final result the programme seeks.'),C('ultimate.s2','根本关键','Trust is the ultimate test of any long-term partnership.','信任是任何長期合作關係最根本的考驗。','the ultimate + test / authority / cause','Adjective: the most basic or important, beyond which one cannot go.','Trust is treated as the decisive, most important criterion.'),C('ultimate.s3','极致例子','For many fans, the live final is the ultimate sporting event.','對許多球迷來說，現場決賽是最極致的體育賽事。','the ultimate in + quality or activity','Adjective: the best, worst, or most extreme example of its kind.','The final is presented as the highest example of the sport.')],[M('The ultimate goal was an early temporary step, not the final result of the programme.','The ultimate goal was the final result the programme aimed to achieve.','Ultimate in this sense means final after a process, not an early step.')],[Q('ultimate.q1','ultimate.s1','meaning','What is the programme’s ultimate goal?','Its final intended result.','Its first temporary step.','A hidden reason for the programme.','The first sense means coming at the end of a process.'),Q('ultimate.q2','ultimate.s2','context','Why call trust the ultimate test of a partnership?','It is the most important or decisive measure.','It is the last meeting on the calendar only.','It is a common type of test paper.','The second sense means most basic or important.'),Q('ultimate.q3','ultimate.s3','distinction','Which phrase uses ultimate for the extreme example?','the ultimate sporting event for devoted fans','the ultimate goal at the end of the project','the ultimate cause beneath the disagreement','The sporting event is described as the best or most extreme of its kind.'),Q('ultimate.q4','ultimate.s1','word-choice','Which phrase refers to a final outcome?','the ultimate result after years of research','the ultimate test of trust','the ultimate in winter coats','“Result after years” points to the final stage.')]);
P('ultimately','From ultimate + -ly, used for a final result or for a basic underlying point.',[C('ultimately.s1','最终结果','The repairs will ultimately save the school money, although they cost a great deal now.','雖然維修目前花費不少，最終仍會為學校省錢。','ultimately + result or outcome','Adverb: when everything is considered, or as the final result.','The long-term outcome is a saving.'),C('ultimately.s2','根本层面','The disagreement was ultimately about who had the authority to approve the plan.','這場分歧歸根結底在於誰有權批准計畫。','ultimately about / based on + fundamental issue','Adverb: at the most basic level of a fact or argument.','The apparent dispute rests on a fundamental question of authority.')],[M('The repairs will ultimately save money, meaning they will never produce any final saving.','The repairs will ultimately save money once their long-term effects are considered.','Ultimately can introduce the final result after considering the whole process.')],[Q('ultimately.q1','ultimately.s1','meaning','What does ultimately signal in the repair example?','The final result after the costs and benefits are considered.','The very first step only.','A hidden demand with a deadline.','The first sense looks at the eventual outcome.'),Q('ultimately.q2','ultimately.s2','context','What was the disagreement ultimately about?','The basic question of who could approve the plan.','The repair invoice’s paper colour.','The school’s final bus route.','The second sense points to the most basic issue.'),Q('ultimately.q3','ultimately.s1','distinction','Which sentence uses ultimately for a result over time?','The new insulation will ultimately lower heating bills.','Ultimately, the quarrel concerns ownership.','The debate is ultimately about authority.','The insulation sentence predicts an eventual outcome.'),Q('ultimately.q4','ultimately.s2','word-choice','Which phrase uses the fundamental-issue sense?','The argument was ultimately about fairness.','The medicine will ultimately take effect.','The project ultimately finished in June.','Fairness is presented as the basic issue beneath the argument.')]);
P('ultimatum','From Latin ultimatum, “the last thing,” based on ultimus “last.”',[C('ultimatum.s1','谈判要求','The union issued an ultimatum: the company had until Friday to accept the safety terms.','工會發出最後通牒：公司必須在星期五前接受安全條款。','issue / give an ultimatum to + person','Noun: a final demand stating what will happen if it is refused.','The demand has a deadline and a stated consequence.'),C('ultimatum.s2','日常警告','Her parent gave her an ultimatum to finish the assignment by dinner or lose screen time.','家長給她最後期限：晚餐前完成作業，否則不能使用螢幕。','an ultimatum about + everyday obligation','Noun: a final warning in daily life with a clear deadline.','The warning sets a deadline and consequence.')],[M('The union issued an ultimatum with no deadline, no demand, and no consequence if it was refused.','The union issued an ultimatum with a Friday deadline and a consequence for refusal.','An ultimatum is a final demand that states what happens if it is refused.')],[Q('ultimatum.q1','ultimatum.s1','meaning','What makes the union’s demand an ultimatum?','It is final and gives a deadline and consequence.','It is an optional suggestion with no deadline.','It is a list of ordinary workplace types.','The formal sense is a final demand stating what follows refusal.'),Q('ultimatum.q2','ultimatum.s2','context','What did the parent’s ultimatum require?','Finish the assignment by dinner or lose screen time.','Finish it whenever convenient with no consequence.','Type the assignment twice in a twinkling.','The everyday sense is a final warning with a clear deadline.'),Q('ultimatum.q3','ultimatum.s1','distinction','Which is a negotiating ultimatum?','Accept the safety terms by Friday or the talks end.','Consider the safety terms when you have time.','The company may want to discuss terms someday.','The first gives a final demand, deadline, and consequence.'),Q('ultimatum.q4','ultimatum.s2','word-choice','Which phrase is natural?','give a teenager an ultimatum about a deadline','offer an ultimatum with no final demand','issue an ultimatum that has no consequence or deadline','An ultimatum is a final warning with a clear deadline.')]);
P('ultra','From Latin ultra, “beyond,” used independently or as a combining form.',[C('ultra.s1','立场极端','The article described the group as ultra because its views went far beyond the usual position.','文章稱該團體立場極端，因為其觀點遠超一般立場。','an ultra + noun / group','Adjective or noun: holding views or habits far beyond the ordinary.','The group’s views are unusually extreme.'),C('ultra.s2','构词前缀','The company installed ultra-modern controls that adjust the temperature automatically.','公司安裝了極其現代化的控制設備，可自動調節溫度。','ultra- + adjective','Prefix: extremely, or beyond the usual range.','Ultra intensifies “modern.”')],[M('The article called the group ultra because it held only moderate, ordinary views.','The article called the group ultra because its views went far beyond the ordinary.','Ultra can describe views or habits that are unusually extreme.')],[Q('ultra.q1','ultra.s1','meaning','Why did the article call the group ultra?','Its views went far beyond the ordinary.','Its views were completely moderate.','It used a modern temperature control.','The independent sense describes extreme views or habits.'),Q('ultra.q2','ultra.s2','context','What does ultra-modern mean?','Extremely modern or beyond the usual range.','Not modern at all.','Modern in exactly two ways.','The prefix ultra intensifies the adjective.'),Q('ultra.q3','ultra.s1','distinction','Which use refers to a group’s extreme outlook?','The ultra rejected every compromise as too moderate.','The ultra-modern lab opened today.','An ultra-clean room holds the samples.','The first uses ultra independently for people with extreme views.'),Q('ultra.q4','ultra.s2','word-choice','Which word uses ultra as a prefix?','ultraclean','an ultra who attends the meeting','a typical opinion','Ultraclean combines ultra- with an adjective to intensify it.')]);
P('ultraclean','A compound of ultra- “extremely” + clean, meaning clean to an unusually high standard.',[C('ultraclean.s1','实验室','The wafers are etched in an ultraclean room to prevent microscopic dust from damaging them.','晶圓在超潔淨室中蝕刻，以免微塵造成損壞。','an ultraclean room / environment','Adjective: clean to an unusually high standard, as in a controlled laboratory room.','The room has strict cleanliness controls for sensitive materials.')],[M('The wafers were processed in an ultraclean room full of dust and uncontrolled contamination.','The wafers were processed in an ultraclean room with carefully controlled dust levels.','Ultraclean describes a room maintained to an unusually high standard of cleanliness.')],[Q('ultraclean.q1','ultraclean.s1','meaning','Why must the wafer room be ultraclean?','Even tiny dust particles could damage the wafers.','The room must contain as much dust as possible.','The room is used for typing documents.','The word means clean to an unusually high standard.'),Q('ultraclean.q2','ultraclean.s1','context','Where might an ultraclean room be used?','In a controlled laboratory or manufacturing space.','In a muddy outdoor field.','As a storm shelter at sea.','Sensitive laboratory work requires exceptional cleanliness.'),Q('ultraclean.q3','ultraclean.s1','distinction','Which environment is ultraclean?','A controlled room where airborne particles are carefully limited.','A room cleaned once but still filled with dust.','A room with no cleaning rules.','Particle control raises cleanliness beyond the ordinary.'),Q('ultraclean.q4','ultraclean.s1','word-choice','Which phrase is natural?','process microchips in an ultraclean room','store dusty boots in an ultraclean room without cleaning them','call a typist ultraclean because they use a keyboard','Sensitive electronics may be made in an exceptionally clean room.')]);
P('ultrasonic','A compound of ultra- + sonic, describing sound beyond the range humans can hear.',[C('ultrasonic.s1','声波','The jeweller used an ultrasonic cleaner to remove dirt from the ring’s tiny crevices.','珠寶商用超音波清洗器清除戒指細小縫隙中的污垢。','ultrasonic waves / cleaner','Adjective: having a frequency above the human hearing range, about 20 kilohertz.','The cleaner uses sound waves too high-pitched for people to hear.')],[M('The ultrasonic signal had a low frequency that every listener could hear clearly.','The ultrasonic signal had a frequency above the range of human hearing.','Ultrasonic waves are higher in frequency than humans can hear.')],[Q('ultrasonic.q1','ultrasonic.s1','meaning','What frequency range is ultrasonic?','Above the range humans can hear, roughly above 20 kilohertz.','Below the lowest sound humans can hear.','Exactly the frequency of ordinary speech.','Ultrasonic describes sound above human hearing.'),Q('ultrasonic.q2','ultrasonic.s1','context','Why can an ultrasonic cleaner reach tiny crevices?','It uses high-frequency sound waves to remove dirt.','It uses only visible violet light.','It works by typing the dirt onto paper.','Ultrasonic waves help clean small spaces.'),Q('ultrasonic.q3','ultrasonic.s1','distinction','Which device uses ultrasonic waves?','A cleaner operating above the human hearing range.','A radio that broadcasts ordinary speech.','A typewriter that prints letters.','The cleaner uses high-frequency sound beyond hearing.'),Q('ultrasonic.q4','ultrasonic.s1','word-choice','Choose the accurate phrase.','ultrasonic sound above about 20 kilohertz','ultrasonic sound audible to every person','ultrasonic light with no sound waves','The source sets the approximate limit above human hearing at 20 kHz.')]);
P('ultrasonics','Formed from ultra- + sonics, naming both the science and practical use of ultrasound-range sound.',[C('ultrasonics.s1','科学','The course introduces ultrasonics and explains how high-frequency sound behaves in different materials.','課程介紹超音波學，說明高頻聲波在不同材料中的行為。','the science of ultrasonics','Noun: the science dealing with sound waves beyond human hearing.','The subject studies very high-frequency sound.'),C('ultrasonics.s2','检测与清洗','The factory uses ultrasonics to find hairline cracks inside metal parts.','工廠使用超音波檢測金屬零件內部的細微裂縫。','use ultrasonics for testing / cleaning','Noun: practical use of ultrasonic waves in testing and cleaning.','High-frequency sound helps reveal hidden cracks.')],[M('The factory used ultrasonics to polish the metal by ordinary visible light without producing sound waves.','The factory used ultrasonics to detect hidden cracks with high-frequency sound waves.','Ultrasonics applies sound beyond human hearing; it is not visible light.')],[Q('ultrasonics.q1','ultrasonics.s1','meaning','What does the science of ultrasonics study?','Sound waves beyond the range humans can hear.','Visible violet light only.','The usual features of a group.','The field studies high-frequency sound.'),Q('ultrasonics.q2','ultrasonics.s2','context','How did the factory use ultrasonics?','To detect hidden cracks in metal.','To type the inspection report without a keyboard.','To cover the factory from rain.','Practical ultrasonics is used for testing and cleaning.'),Q('ultrasonics.q3','ultrasonics.s1','distinction','Which phrase refers to ultrasonics as a science?','a course on sound waves above human hearing','ultrasonics used to inspect a weld','an ultrasonic cleaner in a jewellery shop','The course treats the field of study itself.'),Q('ultrasonics.q4','ultrasonics.s2','word-choice','Which example is a practical application?','using ultrasonics to find cracks inside a pipe','studying the science of high-frequency sound','reading about wave frequencies in a textbook','The inspection uses the technology in practice.')]);
P('ultrasound','A compound of ultra- + sound, referring to high-frequency sound or an examination using it.',[C('ultrasound.s1','医学影像','The ultrasound showed a healthy heartbeat during the pregnancy check.','孕期檢查的超音波影像顯示胎兒心跳正常。','an ultrasound scan / examination','Noun: sound waves above the audible range, or an imaging examination using them.','The scan uses high-frequency sound to form an image.')],[M('The doctor used an ultrasound scan that relied on visible light and no sound waves.','The doctor used an ultrasound scan that formed an image with high-frequency sound waves.','Ultrasound imaging uses sound waves beyond the audible range.')],[Q('ultrasound.q1','ultrasound.s1','meaning','What does an ultrasound examination use to create an image?','Sound waves above the audible range.','Visible ultraviolet rays only.','A typewriter ribbon.','Ultrasound is high-frequency sound used in imaging.'),Q('ultrasound.q2','ultrasound.s1','context','What did the pregnancy ultrasound show?','A healthy heartbeat.','A typographical error in a report.','A distant storm on the ocean.','The scan creates an image of structures inside the body.'),Q('ultrasound.q3','ultrasound.s1','distinction','Which use refers to the medical examination?','She had an ultrasound to check the baby’s development.','Ultrasound waves are above the range of hearing.','The technician measured the wave frequency.','The first describes the imaging procedure.'),Q('ultrasound.q4','ultrasound.s1','word-choice','Which statement is accurate?','An ultrasound scan uses high-frequency sound.','An ultrasound scan is a camera using visible light only.','An ultrasound scan is a one-quarter-dollar coin.','The examination relies on sound beyond ordinary hearing.')]);
P('ultraviolet','From ultra- “beyond” + violet, for invisible radiation beyond violet at the short-wavelength end of visible light.',[C('ultraviolet.s1','电磁辐射','Ultraviolet rays can damage skin after prolonged exposure to strong sunlight.','長時間暴露在強烈陽光下，紫外線會傷害皮膚。','ultraviolet rays / radiation','Adjective or noun: relating to invisible light with a shorter wavelength than visible violet light.','The radiation lies beyond violet in the spectrum.'),C('ultraviolet.s2','灯具与防护','The laboratory uses ultraviolet lamps to sterilize sealed equipment.','實驗室使用紫外線燈為密封設備消毒。','ultraviolet lamp / protection','Adjective: using ultraviolet light, or protecting against it.','The lamps emit ultraviolet light for sterilization.')],[M('The laboratory used ultraviolet lamps that emitted only visible red light and no ultraviolet radiation.','The laboratory used ultraviolet lamps that emitted invisible ultraviolet radiation.','An ultraviolet lamp emits light beyond the visible violet range.')],[Q('ultraviolet.q1','ultraviolet.s1','meaning','Where is ultraviolet radiation relative to visible violet light?','At a shorter wavelength, beyond visible violet.','At a longer wavelength beyond visible red.','At the same wavelength as green light.','Ultraviolet lies beyond the violet end of visible light.'),Q('ultraviolet.q2','ultraviolet.s2','context','Why did the laboratory use ultraviolet lamps?','To sterilize equipment with ultraviolet light.','To produce ordinary sound waves.','To make the room ultraclean by typing.','The lamps use UV radiation for sterilization.'),Q('ultraviolet.q3','ultraviolet.s1','distinction','Which sentence describes ultraviolet rays?','Strong exposure can damage skin.','The rays are visible as ordinary violet light.','The rays are sound waves above human hearing.','UV radiation is invisible and can harm skin.'),Q('ultraviolet.q4','ultraviolet.s2','word-choice','Which phrase uses the lamp sense?','ultraviolet lamps in the sterilization room','ultraviolet rays from strong sunlight','ultraviolet wavelength shorter than visible violet','The lamps use ultraviolet light in a practical application.')]);
P('umbrella','From Italian ombrella, “little shade,” from ombra “shade,” ultimately Latin umbra.',[C('umbrella.s1','雨具','She opened her umbrella when the first heavy drops began to fall.','第一批大雨點落下時，她撐開了雨傘。','open / carry an umbrella','Noun: a folding cloth on a stick that protects someone from rain or strong sun.','The canopy shields her from the rain.'),C('umbrella.s2','统括组织','Several local charities now work under one umbrella organization.','幾個地方慈善團體如今在同一個統籌組織下合作。','under an umbrella + organization / idea','Noun: one organization or idea that covers several smaller ones.','The central body coordinates the smaller charities.')],[M('The umbrella kept the rain off by folding away and leaving her completely uncovered.','The umbrella kept the rain off by spreading its canopy above her.','A physical umbrella protects by covering the person.')],[Q('umbrella.q1','umbrella.s1','meaning','What did she open when the rain began?','A folding cover that shields her from rain.','A central charity organization.','A type of high-frequency sound.','The physical noun protects a person from weather.'),Q('umbrella.q2','umbrella.s2','context','What does one umbrella organization do for several charities?','Provides a shared structure covering smaller groups.','Keeps rain off the charity workers.','Types each charity’s documents.','The figurative sense is an organization coordinating smaller ones.'),Q('umbrella.q3','umbrella.s1','distinction','Which use is literal?','He carried an umbrella through the rain.','The projects sit under one umbrella.','The umbrella group coordinates six teams.','Carrying it through rain uses the physical object.'),Q('umbrella.q4','umbrella.s2','word-choice','Which phrase uses the organizational sense?','a single umbrella body for several agencies','an umbrella opened above a wet traveler','a broken umbrella left by the door','The body covers and coordinates several smaller agencies.')]);
P('umpire','From Old French nonper, “not an equal,” reanalyzed in English after “a noumpire” lost its initial n.',[C('umpire.s1','体育竞赛','The umpire stopped the match when the court became unsafe.','場地變得不安全時，裁判中止了比賽。','an umpire calls / controls a game','Noun: an official who controls a game and ensures that rules are followed.','The official applies the game’s rules.'),C('umpire.s2','仲裁','A retired judge was asked to umpire the dispute between the two companies.','一名退休法官受邀仲裁兩家公司之間的爭議。','umpire a dispute / disagreement','Verb: act as a person who decides an outcome or settles a dispute.','The judge serves as a neutral decision-maker.')],[M('The tennis umpire encouraged both players to ignore every rule and decide the score themselves.','The tennis umpire enforced the rules and made the calls during the match.','An umpire controls a game and makes sure its rules are followed.')],[Q('umpire.q1','umpire.s1','meaning','What does an umpire do during a game?','Controls play and ensures the rules are followed.','Types the players’ names into a form.','Moves the match to a different key.','The sports noun is an official who applies the rules.'),Q('umpire.q2','umpire.s2','context','Why was the retired judge asked to umpire the dispute?','To decide the issue or settle the disagreement.','To coach one company’s employees.','To call a ball out in a baseball game.','The verb means act as a neutral decision-maker.'),Q('umpire.q3','umpire.s1','distinction','Which sentence uses umpire as a noun?','The umpire called the serve out.','She umpired the contract dispute.','The judge was asked to umpire between firms.','The first names the game official.'),Q('umpire.q4','umpire.s2','word-choice','Which sentence uses umpire as a verb?','A mediator was asked to umpire the disagreement.','The umpire checked the court before play.','The umpire signaled that the ball was out.','The mediator acts to decide or settle a dispute.')]);
P('unable','From un- “not” + able, from Latin habilis “easily handled or suitable.”',[C('unable.s1','能力或机会','The technician was unable to repair the device before the laboratory closed.','實驗室關門前，技術員無法修好設備。','be unable to + verb','Adjective: not having the skill, time, or chance to do something.','The technician cannot complete the repair before closing.')],[M('The technician was unable to repair the device, so she repaired it successfully before closing.','The technician was able to repair the device before closing.','Unable means lacking the ability, time, or opportunity to do something.')],[Q('unable.q1','unable.s1','meaning','Why was the technician unable to finish the repair?','She lacked the time or ability before closing.','She completed the repair successfully.','The device was a kind of umbrella.','Unable means not having skill, time, or chance.'),Q('unable.q2','unable.s1','context','If a passenger is unable to travel, what is true?','The passenger cannot make the journey.','The passenger has already arrived.','The passenger is travelling without music.','Unable to travel means cannot travel.'),Q('unable.q3','unable.s1','distinction','Which sentence correctly uses unable?','He was unable to attend the meeting.','He unable attended the meeting.','He was unable the meeting.','“Unable to” is followed by a verb.'),Q('unable.q4','unable.s1','word-choice','Which situation makes someone unable to see a sign?','The sign is hidden behind a wall and they have no view.','They can see it clearly from nearby.','They read it twice.','The first situation removes the opportunity to see it.')]);
P('unacceptable','From un- “not” + acceptable, meaning too bad or wrong to allow or agree to.',[C('unacceptable.s1','标准与规则','The hospital said a three-hour delay in urgent care was unacceptable.','醫院表示，緊急照護延誤三小時是不可接受的。','unacceptable + behavior, condition, or offer','Adjective: so bad or wrong that it cannot be allowed or agreed to.','The delay falls below an acceptable standard.')],[M('The committee called the careful, fair treatment of every applicant unacceptable.','The committee called the unfair rejection of qualified applicants unacceptable.','Unacceptable describes something too bad or wrong to allow or agree to.')],[Q('unacceptable.q1','unacceptable.s1','meaning','Why was the three-hour delay called unacceptable?','It was too serious to be allowed as an acceptable standard.','It was an excellent result everyone agreed to.','It lasted for only a twinkling.','Unacceptable means too bad or wrong to allow or approve.'),Q('unacceptable.q2','unacceptable.s1','context','Which action would a committee likely call unacceptable?','Rejecting qualified applicants unfairly.','Applying the same fair rules to everyone.','Publishing a clear decision process.','Unfair treatment is too wrong to accept.'),Q('unacceptable.q3','unacceptable.s1','distinction','Which use is correct?','The unsafe working condition was unacceptable.','The careful safety check was unacceptable because it was fair.','An acceptable offer is unacceptable by definition.','An unsafe condition falls below allowed standards.'),Q('unacceptable.q4','unacceptable.s1','word-choice','Which phrase is natural?','an unacceptable level of risk','an unacceptable agreement meaning everyone approves','an unacceptable success that meets every requirement','A level of risk can be too high to allow.')]);
P('unaccompanied','From un- “not” + accompanied; the adjective describes someone alone or a performance without another instrument.',[C('unaccompanied.s1','独自出行','The unaccompanied child waited with airport staff until her guardian arrived.','無人陪同的孩子在監護人抵達前由機場人員照看。','an unaccompanied child / traveler','Adjective: travelling or present without another person.','No companion is travelling with the child.'),C('unaccompanied.s2','音乐表演','The singer gave an unaccompanied performance of the folk song.','歌手清唱了那首民歌，沒有任何樂器伴奏。','an unaccompanied song / performance','Adjective: sung or played without another instrument joining in.','The voice is heard without instrumental accompaniment.')],[M('The unaccompanied singer performed with a full orchestra playing behind her.','The singer gave an unaccompanied performance without any instrument joining in.','Unaccompanied in music means without instrumental accompaniment.')],[Q('unaccompanied.q1','unaccompanied.s1','meaning','Why was the child called unaccompanied?','No other person was travelling with her.','She was travelling with both parents.','She was singing without an instrument.','The travel sense means present or travelling alone.'),Q('unaccompanied.q2','unaccompanied.s2','context','What made the folk-song performance unaccompanied?','The singer sang without an instrument.','A child travelled alone to the airport.','The singer had a full orchestra.','The music sense means no other instrument joined in.'),Q('unaccompanied.q3','unaccompanied.s1','distinction','Which phrase uses the travel sense?','an unaccompanied minor on a flight','an unaccompanied vocal performance','an unaccompanied song without piano','A minor on a flight is travelling without an adult companion.'),Q('unaccompanied.q4','unaccompanied.s2','word-choice','Which phrase uses the musical sense?','an unaccompanied solo voice','an unaccompanied child at the gate','an unaccompanied traveler on the train','A solo voice without instrumental support is unaccompanied.')]);
P('unachievable','From un- “not” + achievable, meaning impossible to reach even with effort.',[C('unachievable.s1','目标','The team replaced its unachievable target with a demanding but realistic one.','團隊把無法達成的目標換成一個嚴格但實際的目標。','an unachievable goal / target','Adjective: too difficult to achieve, whatever effort is made.','The target cannot be reached despite effort.')],[M('The team called the modest target unachievable even though every member had already reached it.','The team called the impossible target unachievable and chose a realistic alternative.','If a target has already been reached, it is not unachievable.')],[Q('unachievable.q1','unachievable.s1','meaning','What does an unachievable target mean?','It cannot be reached, however hard the team tries.','It is easy to reach with little effort.','It has already been reached.','The adjective describes a goal too difficult to achieve.'),Q('unachievable.q2','unachievable.s1','context','Why did the team replace its target?','The original target could not realistically be met.','The original target had already been exceeded twice.','The team wanted to type the target.','Unachievable means the goal cannot be attained.'),Q('unachievable.q3','unachievable.s1','distinction','Which goal is unachievable?','A target no team can meet despite every possible effort.','A demanding goal reached by every group.','A goal that needs one more day of work.','The first is impossible to achieve, not merely challenging.'),Q('unachievable.q4','unachievable.s1','word-choice','Which phrase is natural?','an unachievable deadline for the required work','an unachievable goal that everyone has already met','an unachievable task that is effortless','A deadline that cannot be met is unachievable.')]);
P('unadorned','From un- “not” + adorned, the past participle of adorn.',[C('unadorned.s1','装饰','The chapel’s unadorned walls were plain, with no paintings or carved trim.','小教堂沒有裝飾的牆面十分樸素，沒有畫作或雕刻飾條。','unadorned + object / room','Adjective: not decorated or made more attractive than necessary.','The walls have no decorative additions.'),C('unadorned.s2','事实陈述','She gave an unadorned account of the failure, without excuses or embellishment.','她如實陳述了失敗經過，沒有藉口或添油加醋。','an unadorned account / description','Adjective: giving facts exactly as they are, with nothing added to improve them.','The speaker presents the facts plainly.')],[M('She gave an unadorned account by adding invented praise and dramatic details to make the failure seem better.','She gave an unadorned account by stating the facts without added praise or embellishment.','An unadorned account presents facts plainly without decoration or spin.')],[Q('unadorned.q1','unadorned.s1','meaning','What did the chapel’s unadorned walls lack?','Decoration such as paintings or carved trim.','A clear account of the failure.','Any physical wall surface.','The first sense means not decorated.'),Q('unadorned.q2','unadorned.s2','context','How did she give an unadorned account?','She stated the facts without excuses or embellishment.','She added praise to make the failure look better.','She sang the account with an orchestra.','The figurative sense means plain factual reporting.'),Q('unadorned.q3','unadorned.s1','distinction','Which object is literally unadorned?','A plain wall with no pictures or trim.','A report giving the facts without spin.','A musician singing without accompaniment.','The wall has no decorative additions.'),Q('unadorned.q4','unadorned.s2','word-choice','Which phrase uses the factual sense?','an unadorned account of the accident','an unadorned doorway with no carving','an unadorned room with bare walls','An account can be unadorned when it adds no spin.')]);
P('unaffected','From un- “not” + affected, with a figurative sense of being natural rather than put on.',[C('unaffected.s1','未受影响','The village remained unaffected by the brief power cut because it had a backup generator.','由於有備用發電機，短暫停電沒有影響到村莊。','remain unaffected by + event','Adjective: not altered or influenced by an event or situation.','The power cut caused no change in the village’s services.'),C('unaffected.s2','自然真诚','Despite her success, the singer’s manner remained warm and unaffected.','儘管取得成功，這位歌手的舉止仍然親切自然，不矯揉造作。','an unaffected manner / style','Adjective: sincere and relaxed, without effort to impress.','Her behavior is genuine rather than affected.')],[M('The village was unaffected by the flood, although every home was destroyed and residents had to leave.','The village was severely affected by the flood, and residents had to leave.','A place with destroyed homes is affected, not unaffected.')],[Q('unaffected.q1','unaffected.s1','meaning','What does unaffected by the power cut mean?','The village was not changed or disrupted by it.','The village lost all electricity permanently.','The singer acted in a theatrical way.','This sense means not altered or influenced by an event.'),Q('unaffected.q2','unaffected.s2','context','Why is the singer’s manner called unaffected?','It is sincere and relaxed rather than put on.','It is carefully designed to impress everyone.','It is a type of storm.','The second sense describes natural, genuine behavior.'),Q('unaffected.q3','unaffected.s1','distinction','Which sentence uses unaffected for lack of impact?','The backup generator left the clinic unaffected by the outage.','Her unaffected laugh sounded natural.','The singer kept an unaffected style.','The clinic experienced no change from the outage.'),Q('unaffected.q4','unaffected.s2','word-choice','Which phrase uses the natural-manner sense?','an unaffected warmth that felt sincere','unaffected homes after a flood','the building was unaffected by the storm','Warmth and sincerity describe a person’s manner.')]);
P('unaided','From un- “not” + aided, meaning done without help.',[C('unaided.s1','独立完成','The child completed the puzzle unaided, without hints or help from an adult.','孩子沒有提示，也沒有大人幫忙，獨自完成了拼圖。','do / achieve something unaided','Adjective or adverb: done by someone alone without help from a person or tool.','The child works independently.')],[M('She solved the puzzle unaided after her tutor guided her through every step.','She solved the puzzle unaided without receiving hints or guidance.','Unaided means without help, so guided assistance contradicts it.')],[Q('unaided.q1','unaided.s1','meaning','How did the child complete the puzzle unaided?','Without help or hints from another person.','With an adult explaining every step.','By using a typewriter.','Unaided means done alone without help.'),Q('unaided.q2','unaided.s1','context','What is the unaided eye?','Sight used without a visual aid such as binoculars.','Sight supported by a telescope.','A way to hear ultrasonic waves.','Unaided can describe seeing without a tool.'),Q('unaided.q3','unaided.s1','distinction','Which task was completed unaided?','She solved it without a tutor or calculator.','She solved it after receiving step-by-step help.','She watched someone else solve it.','No person or tool assisted her.'),Q('unaided.q4','unaided.s1','word-choice','Choose the correct phrase.','an unaided attempt to lift the box','an unaided lift using a crane and three assistants','an unaided eye looking through binoculars','The first involves no external assistance.')]);
P('unaltered','From un- “not” + altered, the past participle of alter.',[C('unaltered.s1','保持原样','The archivist stored the unaltered letter in a protective sleeve.','檔案管理員把未經改動的信件存放在保護套中。','remain / leave something unaltered','Adjective: staying exactly as it was, with no change made.','No revision or modification was made to the letter.')],[M('The archivist called the letter unaltered after replacing its original words with a rewritten version.','The archivist kept the letter unaltered and preserved its original wording.','A rewritten document has been changed, so it is not unaltered.')],[Q('unaltered.q1','unaltered.s1','meaning','What happened to an unaltered letter?','It stayed exactly as it was.','Its wording was rewritten.','It was translated into another language.','Unaltered means no change was made.'),Q('unaltered.q2','unaltered.s1','context','Why did the archivist keep the letter unaltered?','To preserve its original wording and form.','To make it more attractive with new decorations.','To turn it into a type of report.','Keeping it unchanged preserves the original document.'),Q('unaltered.q3','unaltered.s1','distinction','Which copy is unaltered?','A scan identical to the original document.','A revised version with several paragraphs changed.','A translation into a different language.','The identical scan has no changes.'),Q('unaltered.q4','unaltered.s1','word-choice','Which phrase is natural?','the unaltered original photograph','the unaltered picture after heavy editing','the unaltered rewrite with different wording','The untouched original is unaltered.')]);
P('unambiguous','From un- “not” + ambiguous, ultimately from Latin ambigere “to be uncertain.”',[C('unambiguous.s1','清楚明确','The survey gave an unambiguous answer: every respondent chose option B.','調查得到明確無歧義的答案：每位受訪者都選了 B。','an unambiguous answer / result','Adjective: clear in meaning and allowing only one reading.','There is no uncertainty about which option was selected.'),C('unambiguous.s2','语言结构','The contract uses unambiguous wording so neither party can interpret the deadline in two ways.','合約措辭明確，雙方都無法把期限解讀成兩種意思。','unambiguous language / wording','Adjective: having no double meaning in words or grammar.','The wording cannot be read in two different ways.')],[M('The contract was unambiguous because its deadline could mean either Monday or Friday.','The contract was unambiguous because it stated one clear deadline with no second reading.','If a deadline has two possible meanings, the wording is ambiguous.')],[Q('unambiguous.q1','unambiguous.s1','meaning','Why was the survey answer unambiguous?','It allowed only one clear reading.','It gave two equally possible answers.','It contained an unclear deadline.','The adjective means clear in meaning with no alternative reading.'),Q('unambiguous.q2','unambiguous.s2','context','Why did the contract need unambiguous wording?','So the deadline could not be interpreted in two ways.','So every reader could choose any date.','So the document could be typed twice.','This sense concerns words and grammar with no double meaning.'),Q('unambiguous.q3','unambiguous.s1','distinction','Which result is unambiguous?','All respondents selected option B and no other option.','Half chose A and half chose B.','The result was reported using unclear wording.','The first result has one definite interpretation.'),Q('unambiguous.q4','unambiguous.s2','word-choice','Which phrase uses the language sense?','an unambiguous clause naming one payment date','an unambiguous answer to a poll','an unambiguous result with one winner','The clause’s wording has no double meaning.')]);
P('unanimity','From Latin unanimus, “of one mind,” + -ity, naming complete agreement.',[C('unanimity.s1','一致同意','The proposal passed with unanimity after every board member voted in favour.','董事會每位成員都投贊成票，提案一致通過。','with / by unanimity','Noun: the state in which all people agree.','Every member shares the same decision.')],[M('The motion passed with unanimity even though half the board voted against it.','The motion passed with unanimity because every board member supported it.','Unanimity requires everyone to agree, not a split vote.')],[Q('unanimity.q1','unanimity.s1','meaning','What does unanimity mean in a board vote?','Every member agrees.','Only the chair agrees.','Half agree and half disagree.','The noun names a state of complete agreement.'),Q('unanimity.q2','unanimity.s1','context','Why did the proposal pass with unanimity?','All board members voted in favour.','Several members opposed it.','The vote was delayed for two weeks.','The full board shared the same decision.'),Q('unanimity.q3','unanimity.s1','distinction','Which result shows unanimity?','Every judge selects the same winner.','Three judges choose one winner and two choose another.','No judge submits a decision.','Unanimity means everyone agrees on the result.'),Q('unanimity.q4','unanimity.s1','word-choice','Which phrase is natural?','the committee reached unanimity on the plan','the committee reached unanimity while holding three opposing views','the unanimity of a single person alone','A group reaches unanimity when all agree.')]);
P('unanimous','From Latin unanimis, “of one mind,” from unus “one” + animus “mind.”',[C('unanimous.s1','表决','The panel was unanimous in selecting the coastal site for the new station.','評審團一致選定海岸地點作為新車站的建址。','be unanimous in + decision / vote','Adjective: sharing one opinion so that every member agrees.','Every panel member selects the same site.'),C('unanimous.s2','一致立场','Residents were unanimous in opposing the closure of the only village clinic.','居民一致反對關閉村裡唯一的診所。','be unanimous in doing / about + proposal','Adjective: all of one mind about a proposal.','Everyone shares the same position on the proposal.')],[M('The panel was unanimous in selecting the site even though half its members voted for a different location.','The panel was unanimous in selecting the site because every member chose it.','A unanimous decision requires agreement by everyone in the group.')],[Q('unanimous.q1','unanimous.s1','meaning','What does it mean that the panel was unanimous?','Every panel member agreed on the same choice.','Only the chair made a choice.','The panel had no opinion.','The first sense requires every member to share one opinion.'),Q('unanimous.q2','unanimous.s2','context','Why were residents unanimous in opposing the closure?','They all shared the same opposition to the proposal.','Some wanted closure and some opposed it.','They had not heard about the proposal.','The phrase says the whole group held one view.'),Q('unanimous.q3','unanimous.s1','distinction','Which result is a unanimous vote?','All seven judges select the same winner.','Four judges select one winner and three select another.','Only one judge submits a vote.','Every judge agrees on the result.'),Q('unanimous.q4','unanimous.s2','word-choice','Which phrase fits the shared-position sense?','The committee was unanimous in rejecting the cut.','The committee had one unanimous member.','The committee made a divided decision.','The whole committee shared the view that the cut should be rejected.')]);
P('unanswered','From un- “not” + answered, the past participle of answer.',[C('unanswered.s1','回应','Several residents’ complaints went unanswered for weeks.','好幾週都沒有人回應居民的投訴。','go / remain unanswered','Adjective: not given an answer, or not matched by a reply or score.','No response was given to the complaints.')],[M('The residents’ complaints went unanswered because officials replied to every one of them.','The residents’ complaints went unanswered because officials gave no reply.','Unanswered means no answer or reply was given.')],[Q('unanswered.q1','unanswered.s1','meaning','What happened to the residents’ complaints?','They received no answer for weeks.','They were resolved immediately.','They were answered twice.','Unanswered means not given a reply.'),Q('unanswered.q2','unanswered.s1','context','If a question remains unanswered, what is missing?','A response to the question.','A clear question.','A typewriter to record the answer.','An unanswered question has not received a reply.'),Q('unanswered.q3','unanswered.s1','distinction','Which message went unanswered?','An email that received no reply.','A letter with a detailed response.','A question answered by the teacher.','The first received no answer.'),Q('unanswered.q4','unanswered.s1','word-choice','Choose the natural use.','The appeal went unanswered until Monday.','The appeal went unanswered because it received three replies.','An unanswered reply explained the decision fully.','No response arrived until Monday.')]);
P('unanticipated','From un- “not” + anticipated, the past participle of anticipate.',[C('unanticipated.s1','意外后果','The dry season brought unanticipated costs when the town had to truck in water.','乾季迫使小鎮用卡車運水，因此帶來了意想不到的費用。','unanticipated + event, cost, or result','Adjective: not thought of in advance.','The costs had not been expected before the drought.')],[M('The extra cost was unanticipated even though the budget had listed and calculated it in advance.','The extra cost was unanticipated because no one had planned for water deliveries.','Unanticipated means not thought of or planned in advance.')],[Q('unanticipated.q1','unanticipated.s1','meaning','Why were the water-delivery costs unanticipated?','They had not been thought of before the drought.','They were carefully included in the budget.','They were expected every year.','The adjective means not anticipated in advance.'),Q('unanticipated.q2','unanticipated.s1','context','What is an unanticipated delay?','A delay people had not expected beforehand.','A delay announced and planned months earlier.','A delay that never occurs.','Unanticipated describes an unexpected event.'),Q('unanticipated.q3','unanticipated.s1','distinction','Which cost is unanticipated?','A new emergency fee no planner had considered.','A scheduled annual payment already in the budget.','A bill described to everyone beforehand.','The emergency fee was not planned in advance.'),Q('unanticipated.q4','unanticipated.s1','word-choice','Which phrase is natural?','unanticipated expenses after the storm','unanticipated costs listed in full before the storm','an unanticipated plan known to everyone','Expenses not foreseen are unanticipated.')]);
P('unassailable','From un- “not” + assailable, “able to be attacked,” from assail.',[C('unassailable.s1','防守与安全','The fortress occupied a steep island and was considered unassailable by sea.','堡壘位於陡峭島嶼上，被認為從海上無法攻陷。','an unassailable fortress / position','Adjective: too strong or well defended to be attacked successfully.','Its defenses make a successful attack seem impossible.'),C('unassailable.s2','论证与证据','The auditor built an unassailable case from signed records and verified payments.','稽核員根據簽署紀錄和核實付款建立了無可辯駁的案件。','an unassailable case / argument','Adjective: impossible to criticize or prove wrong.','The evidence leaves no sound basis for challenging the case.')],[M('The castle was unassailable because its walls had no defenders and every gate stood open.','The castle was unassailable because its walls and guarded gates made attack extremely difficult.','Unassailable means too well defended to attack successfully.')],[Q('unassailable.q1','unassailable.s1','meaning','Why was the island fortress considered unassailable?','Its defenses made a successful attack seem impossible.','Its gates were open and unguarded.','It was impossible to inspect the accounts.','The first sense describes a position too well defended to attack.'),Q('unassailable.q2','unassailable.s2','context','Why was the auditor’s case unassailable?','Verified evidence made it impossible to prove wrong.','It had no records or supporting evidence.','It was physically surrounded by a wall.','The figurative sense means impossible to criticize or refute.'),Q('unassailable.q3','unassailable.s1','distinction','Which position is physically unassailable?','A cliff-top fort protected by strong walls and guards.','A claim that cannot be disproved by evidence.','A report with several obvious factual errors.','The fort is too well defended to attack successfully.'),Q('unassailable.q4','unassailable.s2','word-choice','Which phrase uses the argument sense?','an unassailable case supported by audited records','an unassailable castle surrounded by cliffs','an unassailable fortress with weak open gates','A well-supported case cannot easily be criticized or disproved.')]);
P('unassuming','From un- “not” + assuming, the present participle of assume in the sense “take to oneself.”',[C('unassuming.s1','谦逊','The unassuming scientist answered questions quietly and never boasted about her awards.','這位謙遜的科學家安靜地回答問題，從不炫耀自己的獎項。','an unassuming person / manner','Adjective: not trying to seem more important than one really is.','She does not seek status or attention.')],[M('The unassuming scientist constantly boasted that she was more important than every colleague.','The unassuming scientist discussed her work without trying to appear more important than others.','An unassuming person does not try to seem especially important.')],[Q('unassuming.q1','unassuming.s1','meaning','How did the unassuming scientist behave?','She avoided boasting or acting more important than others.','She constantly demanded attention.','She rejected every question angrily.','Unassuming describes someone who does not seek to seem important.'),Q('unassuming.q2','unassuming.s1','context','Which manner is unassuming?','A quiet, modest manner that does not show off.','A boastful speech about personal status.','A threatening attitude toward every colleague.','The adjective means modest and not self-important.'),Q('unassuming.q3','unassuming.s1','distinction','Which person is unassuming?','A prize winner who talks modestly about the team’s work.','A prize winner who claims all credit and belittles everyone.','A manager who refuses to hear disagreement.','The first person is modest and not trying to impress.'),Q('unassuming.q4','unassuming.s1','word-choice','Choose the natural phrase.','an unassuming neighbour who never boasts','an unassuming celebrity demanding constant praise','an unassuming leader who calls everyone inferior','Not boasting fits the meaning.')]);
P('unattainable','From un- “not” + attainable, from attain + -able.',[C('unattainable.s1','目标与机会','For many families, buying a home in the city remains unattainable despite years of saving.','儘管多年儲蓄，對許多家庭來說，在城裡買房仍遙不可及。','an unattainable goal / price / standard','Adjective: beyond one’s power to reach, even with considerable effort.','The families cannot reach the required price despite trying hard.')],[M('The modest goal was unattainable even though everyone achieved it easily on the first day.','The high property price made home ownership unattainable for many families.','If a goal is easily achieved, it is not unattainable.')],[Q('unattainable.q1','unattainable.s1','meaning','What does unattainable home ownership mean here?','Families cannot reach it even after considerable effort.','It is easily available to every family.','It has already been achieved by everyone.','The adjective means beyond a person’s power to reach.'),Q('unattainable.q2','unattainable.s1','context','Why is the city home price unattainable for some families?','It remains beyond their reach despite years of saving.','It is below their budget.','They have already bought several homes there.','The price cannot be reached with their available resources.'),Q('unattainable.q3','unattainable.s1','distinction','Which standard is unattainable?','A requirement no applicant can meet despite sustained effort.','A target every applicant reaches easily.','A goal already achieved last week.','The first is beyond anyone’s power to reach.'),Q('unattainable.q4','unattainable.s1','word-choice','Which phrase is natural?','an unattainable level of access for low-income households','an unattainable goal already reached by all','an unattainable task needing almost no effort','The access level is beyond the households’ reach.')]);
P('unattractive','From un- “not” + attractive, describing appearance or lack of value or interest.',[C('unattractive.s1','外观','The building is unattractive from the street, but its interior is bright and spacious.','這棟建築從街上看並不好看，但室內明亮寬敞。','an unattractive building / appearance','Adjective: not pleasant to look at.','The building’s exterior is not visually pleasing.'),C('unattractive.s2','条件与价值','The low salary made the offer unattractive to experienced engineers.','低薪使這份工作對有經驗的工程師缺乏吸引力。','an unattractive offer / prospect','Adjective: not valuable or interesting enough to make someone want it.','The offer lacks enough value to appeal to the candidates.')],[M('The salary package was unattractive to engineers because it offered exceptionally high pay and generous benefits.','The low salary and limited benefits made the offer unattractive to engineers.','An unattractive offer lacks value or appeal; high pay and benefits would usually attract candidates.')],[Q('unattractive.q1','unattractive.s1','meaning','Why was the building described as unattractive?','Its appearance was not pleasant to look at.','Its salary was too low.','It offered no job to engineers.','The first sense concerns visual appearance.'),Q('unattractive.q2','unattractive.s2','context','Why did the low salary make the offer unattractive?','It was not valuable enough to appeal to experienced engineers.','The building had an unpleasant exterior.','The engineers all accepted it eagerly.','The second sense means lacking value or interest to attract someone.'),Q('unattractive.q3','unattractive.s1','distinction','Which use is about looks?','an unattractive old façade','an unattractive salary package','an unattractive investment return','The façade is unpleasant to see.'),Q('unattractive.q4','unattractive.s2','word-choice','Which phrase uses the appeal sense?','an unattractive job offer with very little pay','an unattractive colour on the wall','an unattractive shape of the tower','The job lacks value to prospective employees.')]);
P('unavailable','Formed with un- “not” + available; the prefix reverses the adjective’s sense.',[C('unavailable.s1','无法取得','The medication was unavailable at the local pharmacy until the next delivery arrived.','下一批藥送達前，當地藥局買不到這種藥。','be unavailable for use / purchase / comment','Adjective: not obtainable, or not free to meet, work, or be used.','The medicine cannot be obtained at the moment.')],[M('The manager was unavailable for comment because she was sitting in the interview room ready to speak.','The manager was unavailable for comment because she was away from the office.','Unavailable means not free to meet or speak, or not obtainable.')],[Q('unavailable.q1','unavailable.s1','meaning','Why was the medicine unavailable?','It could not be obtained before the next delivery.','It was stocked in every nearby pharmacy.','It was already prescribed and delivered.','Unavailable means not obtainable for use or purchase.'),Q('unavailable.q2','unavailable.s1','context','What does “the manager is unavailable for comment” mean?','The manager is not free to speak at that time.','The manager has already given a comment.','The manager is not a manager.','A person can be unavailable when not free to meet or comment.'),Q('unavailable.q3','unavailable.s1','distinction','Which item is unavailable?','A medicine temporarily out of stock.','A medicine on the shelf ready to buy.','A manager sitting in an interview waiting to speak.','The out-of-stock medicine cannot be obtained.'),Q('unavailable.q4','unavailable.s1','word-choice','Which phrase is natural?','The director is unavailable this afternoon.','The director is unavailable because she is free all afternoon.','The unavailable meeting happened in the past but can be attended now.','The first says the director is not free to meet.')]);
P('unavoidable','From un- “not” + avoidable, meaning impossible to prevent or certain to occur.',[C('unavoidable.s1','风险与必然性','Some delay was unavoidable because the mountain pass was closed by snow.','由於山口被大雪封閉，部分延誤無法避免。','an unavoidable delay / consequence','Adjective: impossible to prevent, or certain to happen.','The closure makes some delay impossible to prevent.')],[M('The delay was unavoidable even though the pass stayed open and the route remained clear.','The delay was unavoidable because heavy snow closed the only mountain pass.','An unavoidable event cannot be prevented under the circumstances.')],[Q('unavoidable.q1','unavoidable.s1','meaning','Why was some delay unavoidable?','Snow closed the only route through the pass.','The roads were clear and open.','The trip had been cancelled in advance.','The delay could not be prevented given the closed route.'),Q('unavoidable.q2','unavoidable.s1','context','What does an unavoidable consequence mean?','It is impossible to prevent under the circumstances.','It can easily be avoided by doing nothing.','It has not happened and cannot happen.','Unavoidable can mean impossible to prevent or certain to occur.'),Q('unavoidable.q3','unavoidable.s1','distinction','Which delay is unavoidable?','A train waits because a fallen tree blocks the only track.','A train waits despite an empty, clear track and no reason.','A train leaves on schedule.','The blocked track makes the wait impossible to prevent.'),Q('unavoidable.q4','unavoidable.s1','word-choice','Which phrase is natural?','an unavoidable risk of injury in the storm','an unavoidable delay that was prevented before it began','an unavoidable event that is certain never to happen','Risk in the dangerous storm cannot be fully prevented.')]);
P('unavoidably','From unavoidable + -ly, meaning in a manner that cannot be avoided.',[C('unavoidably.s1','延误','The flight was unavoidably delayed after ice closed the only runway.','唯一跑道因結冰關閉後，航班不得不延誤。','unavoidably + verb or adjective','Adverb: in a manner that cannot be avoided.','With no usable runway, the delay could not be prevented.')],[M('The flight was unavoidably delayed even though the runway was clear and the aircraft departed on time.','The flight was unavoidably delayed because ice closed the runway.','Unavoidably means the delay could not be prevented, so a timely departure contradicts it.')],[Q('unavoidably.q1','unavoidably.s1','meaning','What does unavoidably delayed mean?','The delay could not be prevented.','The delay was chosen for convenience.','The flight departed early.','The adverb means in a way that cannot be avoided.'),Q('unavoidably.q2','unavoidably.s1','context','Why was the flight unavoidably delayed?','Ice closed the only runway.','The runway was open and clear.','The plane arrived before schedule.','The closure left no way to depart on time.'),Q('unavoidably.q3','unavoidably.s1','distinction','Which sentence uses unavoidably correctly?','The bridge was unavoidably closed after a structural failure.','The bridge was unavoidably open because no repairs were needed.','The bridge was unavoidably repaired ahead of schedule by choice.','A structural failure forces the closure.'),Q('unavoidably.q4','unavoidably.s1','grammar','Which word form is the adverb?','The project was unavoidably postponed.','The project faced an unavoidable delay.','The delay was unavoidable.','Unavoidably modifies the verb postponed.')]);
P('unaware','From un- “not” + aware, meaning lacking knowledge or noticing.',[C('unaware.s1','缺乏信息','He was unaware of the road closure until he reached the blocked bridge.','他到了被封鎖的橋邊才知道道路已經封閉。','be unaware of + fact or event','Adjective: not knowing that something exists or is happening.','He does not know about the closure before arriving.'),C('unaware.s2','没注意到','She was so focused on the book that she was unaware of people entering the room.','她全神貫注看書，沒有注意到有人走進房間。','be unaware that + event is happening','Adjective: not noticing what is going on around you.','Her attention is elsewhere, so she does not notice the arrivals.')],[M('He was unaware of the road closure because he had read the official warning and knew it was in place.','He was unaware of the road closure because he had not seen the warning.','If he had read and understood the warning, he would be aware of the closure.')],[Q('unaware.q1','unaware.s1','meaning','Why was he unaware of the road closure?','He did not know it was happening until he reached the bridge.','He had read the warning and knew about it.','He was the person who closed the road.','This sense means not knowing a fact or event.'),Q('unaware.q2','unaware.s2','context','What did the focused reader fail to notice?','People entering the room around her.','The meaning of every word in the book.','The fact that the room was empty.','The second sense is not noticing nearby activity.'),Q('unaware.q3','unaware.s1','distinction','Which sentence means “not knowing a fact”?','They were unaware that the meeting had moved to Friday.','He was unaware of the children walking behind him.','She was unaware of the noise around her.','The first states lack of knowledge about a schedule change.'),Q('unaware.q4','unaware.s2','word-choice','Which use focuses on noticing surroundings?','He was unaware of the cyclist passing beside him.','She was unaware that her visa had expired.','They were unaware that the rules had changed last month.','The cyclist passes nearby, but he does not notice it.')]);
P('unbalance','From un- “not” + balance, meaning to upset a physical or mental equilibrium.',[C('unbalance.s1','平衡','One heavy crate unbalanced the cart and made it tip toward the curb.','一個沉重的木箱使手推車失去平衡，向路緣傾斜。','unbalance + object / person','Verb: upset the physical or mental balance of someone or something.','The uneven load shifts the cart’s balance.')],[M('The crate unbalanced the cart while keeping its load perfectly even and the cart level.','The crate unbalanced the cart by shifting too much weight to one side.','To unbalance a cart is to upset its even physical balance.')],[Q('unbalance.q1','unbalance.s1','meaning','What happened when the crate unbalanced the cart?','Its uneven load made it tip to one side.','It stayed perfectly level.','It became a balanced pair of wheels.','Unbalance means upset physical balance.'),Q('unbalance.q2','unbalance.s1','context','What could unbalance a person emotionally?','A sudden stressful event that disrupts their stability.','A quiet routine that leaves them calm.','A clear answer on a survey.','The verb can refer to disturbing mental as well as physical balance.'),Q('unbalance.q3','unbalance.s1','distinction','Which situation unbalances an object?','A heavy box on one side makes the cart tip.','Equal weights are placed evenly on both sides.','The cart is parked on flat ground with no load.','Uneven weight upsets the cart’s balance.'),Q('unbalance.q4','unbalance.s1','word-choice','Choose the correct sentence.','A sudden shock unbalanced her concentration.','A sudden shock unbalanced her by making everything more stable.','The cart unbalanced because its load was perfectly even.','A shock can disrupt someone’s mental equilibrium.')]);
P('unbearable','From un- “not” + bearable, from bear “endure.”',[C('unbearable.s1','难以忍受','The attic became unbearable during the heat wave, so the family slept downstairs.','熱浪期間，閣樓變得難以忍受，因此一家人改睡在樓下。','unbearable + heat, pain, noise, or situation','Adjective: so unpleasant, painful, or annoying that one cannot accept or endure it.','The heat is too uncomfortable to endure.')],[M('The quiet cool attic was unbearable because it was comfortable and caused no discomfort.','The hot, airless attic was unbearable during the heat wave.','Unbearable describes something too unpleasant or painful to endure.')],[Q('unbearable.q1','unbearable.s1','meaning','Why was the attic unbearable during the heat wave?','It was too hot and uncomfortable to endure.','It was cool and comfortable.','It was a quiet place with perfect airflow.','The adjective means too unpleasant to accept or endure.'),Q('unbearable.q2','unbearable.s1','context','Which noise would be unbearable?','A continuous piercing alarm that prevents sleep.','A soft sound that does not disturb anyone.','A short quiet click once a day.','A severe ongoing annoyance can be unbearable.'),Q('unbearable.q3','unbearable.s1','distinction','Which sentence uses unbearable correctly?','The pain became unbearable after the medicine wore off.','The pain was unbearable because it was absent.','The comfortable room was unbearable because everyone enjoyed it.','Pain too severe to endure is unbearable.'),Q('unbearable.q4','unbearable.s1','word-choice','Choose the natural phrase.','an unbearable delay in the sweltering heat','an unbearable comfort that nobody minds','an unbearable quiet room that is perfectly pleasant','Extreme discomfort can make a delay unbearable.')]);
P('unbeatable','From un- “not” + beatable, from beat + -able; it can praise a very good offer.',[C('unbeatable.s1','竞赛与优势','The defending champions looked unbeatable after winning every match in the season.','衛冕冠軍整季每場都贏，看起來無人能敵。','an unbeatable team / record / price','Adjective: not able to be beaten in a contest, or excellent beyond rivalry.','No opponent has managed to defeat the team.'),C('unbeatable.s1','价格与品质','At that price, the repair package is unbeatable for small businesses.','以這個價格來說，這套維修服務對小企業而言無可匹敵。','unbeatable value / offer','Adjective: exceptionally good or advantageous compared with alternatives.','The price and service offer unusual value.')],[M('The team was unbeatable because every opponent defeated it comfortably.','The team was unbeatable because it won every match against its opponents.','Unbeatable means not able to be beaten in a contest.')],[Q('unbeatable.q1','unbeatable.s1','meaning','Why did the champions look unbeatable?','They won every match and no opponent defeated them.','They lost every match.','They had not played a game.','The contest sense means not able to be beaten.'),Q('unbeatable.q2','unbeatable.s1','context','Why was the repair package called unbeatable at that price?','It offered exceptional value compared with alternatives.','It was too expensive for anyone to choose.','It could not repair anything.','Unbeatable can praise an exceptionally good offer.'),Q('unbeatable.q3','unbeatable.s1','distinction','Which phrase uses the competition sense?','an unbeaten champion with an unbeatable record','an unbeatable price on a repair plan','an offer that is excellent value','The record is difficult or impossible for opponents to beat.'),Q('unbeatable.q4','unbeatable.s1','word-choice','Which sentence uses the value sense?','The hotel’s central location at that rate is unbeatable.','The player was unbeatable after winning the final.','The record proved unbeatable in the race.','The hotel is praised as exceptionally good value.')]);
P('unbecoming','From un- “not” + becoming, in the older sense “suitable or flattering.”',[C('unbecoming.s1','行为与职位','The judge said the insulting remarks were unbecoming of someone in public office.','法官表示，侮辱性言論不符合公職人員的身分。','be unbecoming of + role or position','Adjective: not suitable or proper for someone in a particular position.','The remarks do not meet standards expected of an officeholder.'),C('unbecoming.s2','衣着外观','The wide-brimmed hat was unbecoming on him and made his face look smaller.','那頂寬簷帽戴在他頭上不太好看，讓他的臉顯得更小。','an unbecoming hat / colour / style','Adjective: not making someone look attractive when worn.','The hat is unflattering on the wearer.')],[M('The insulting remarks were becoming of a judge because they were respectful and proper.','The insulting remarks were unbecoming of a judge because they were disrespectful.','Unbecoming means improper for the role, the opposite of becoming or fitting.')],[Q('unbecoming.q1','unbecoming.s1','meaning','Why were the remarks unbecoming of a judge?','They were improper for someone in that position.','They were respectful and entirely suitable.','They were a flattering hat.','The first sense is behavior not suitable for a role.'),Q('unbecoming.q2','unbecoming.s2','context','Why was the hat unbecoming on him?','It did not make him look attractive.','It was proper behavior for a judge.','It was too small to wear at all.','The clothing sense means unflattering when worn.'),Q('unbecoming.q3','unbecoming.s1','distinction','Which use concerns conduct?','Such rude language is unbecoming of a teacher.','That colour is unbecoming on me.','The hat was unbecoming with the coat.','The first describes behavior inappropriate to a position.'),Q('unbecoming.q4','unbecoming.s2','word-choice','Which phrase uses the appearance sense?','an unbecoming jacket that makes the outfit look awkward','an unbecoming remark by the chairperson','unbecoming conduct in court','The jacket is unflattering when worn.')]);
P('unbelievable','From un- “not” + believable, from believe + -able.',[C('unbelievable.s1','令人难信','The speed of the evacuation was unbelievable given the size of the building.','考慮到建築物的規模，撤離速度快得令人難以置信。','an unbelievable event / claim','Adjective: difficult to believe because very surprising or unlikely.','The result is so surprising that it is hard to accept as true.'),C('unbelievable.s2','极佳或极大','They scored an unbelievable goal in the final minute of the match.','他們在比賽最後一分鐘踢進了一個精彩絕倫的進球。','unbelievable + success, size, or quality','Adjective: extremely good or large, used to emphasize how impressive something is.','The adjective intensifies praise for the goal.')],[M('The unbelievable claim was easy to believe because it was ordinary, expected, and fully documented.','The unbelievable claim was so surprising that readers found it difficult to accept.','Unbelievable in this sense describes something very surprising or unlikely.')],[Q('unbelievable.q1','unbelievable.s1','meaning','Why was the evacuation speed unbelievable?','It was surprisingly fast for such a large building.','It was expected and completely ordinary.','It took several months.','This sense means difficult to believe because surprising.'),Q('unbelievable.q2','unbelievable.s2','context','Why did the crowd call the goal unbelievable?','It was extraordinarily impressive.','It was a routine pass that missed the goal.','It was impossible to see because of fog.','The emphatic sense praises something exceptionally good.'),Q('unbelievable.q3','unbelievable.s1','distinction','Which sentence uses unbelievable for improbability?','The witness’s unlikely story was unbelievable to the jury.','She scored an unbelievable goal in stoppage time.','The meal was unbelievably delicious.','The jury found the story difficult to accept as true.'),Q('unbelievable.q4','unbelievable.s2','word-choice','Which phrase uses the emphatic praise sense?','an unbelievable performance that amazed the audience','an unbelievable excuse no one thought could be true','an unbelievable claim contradicted by every record','The performance is praised as extremely impressive.')]);
P('unbent','From un- “not” + bent, the past participle of bend.',[C('unbent.s1','形状','The metal rod remained unbent after the light impact.','輕微撞擊後，金屬桿仍保持筆直，沒有彎曲。','remain / keep something unbent','Adjective: straight because nothing has forced it to curve.','The rod kept its straight shape.'),C('unbent.s2','不屈服','Despite years of criticism, the journalist remained unbent in her defence of the source.','儘管多年來遭受批評，記者仍堅定捍衛消息來源。','remain unbent under pressure','Adjective: unwilling to submit to pressure from others.','The journalist does not give in to the criticism.')],[M('The wire was unbent even though it had been folded sharply into a loop.','The wire was unbent because it remained straight without being forced to curve.','A wire folded into a loop is bent, not unbent.')],[Q('unbent.q1','unbent.s1','meaning','What does an unbent metal rod look like?','It remains straight without a curve.','It has been folded into a loop.','It is unwilling to accept criticism.','The physical sense means straight because it has not been bent.'),Q('unbent.q2','unbent.s2','context','Why was the journalist described as unbent?','She refused to yield to pressure or criticism.','Her notes were physically straight.','She changed her view immediately.','The figurative sense means not submitting to pressure.'),Q('unbent.q3','unbent.s1','distinction','Which use describes shape?','The unbent wire lay straight on the table.','He stayed unbent under public pressure.','The reporter remained unbent despite threats.','The wire sentence describes a physical form.'),Q('unbent.q4','unbent.s2','word-choice','Which use is figurative?','She remained unbent despite demands to reveal her source.','The rod was unbent after the impact.','A straight unbent strip was placed on the desk.','The journalist refuses to give in to pressure.')]);
P('unbiased','From un- “not” + biased, meaning free from unfair preference.',[C('unbiased.s1','公平判断','The review panel used unbiased sources from several independent research groups.','評審小組使用了來自多個獨立研究團隊的無偏見資料來源。','an unbiased report / source / judgment','Adjective: giving equal treatment to all sides without favouring any.','The panel considers evidence from different sides fairly.')],[M('The report was unbiased because it used only evidence from the author’s closest allies and ignored every opposing source.','The report was unbiased because it compared independent sources from all sides.','An unbiased account does not unfairly favour one side or ignore opposing evidence.')],[Q('unbiased.q1','unbiased.s1','meaning','What makes a report unbiased?','It treats sides fairly without favouring one.','It uses evidence from only one ally.','It refuses to examine evidence.','Unbiased means free from unfair preference.'),Q('unbiased.q2','unbiased.s1','context','Why did the panel seek unbiased sources?','To judge the issue without favouring one side.','To confirm only its existing opinion.','To make its wording ambiguous.','Independent balanced sources help prevent unfair preference.'),Q('unbiased.q3','unbiased.s1','distinction','Which reviewer is unbiased?','One who checks evidence for and against each claim.','One who accepts only a friend’s evidence.','One who rejects every opposing view automatically.','The first gives fair consideration to both sides.'),Q('unbiased.q4','unbiased.s1','word-choice','Which phrase is natural?','an unbiased assessment of all candidates','an unbiased assessment that favours one candidate unfairly','an unbiased report ignoring half the evidence','An unbiased assessment evaluates candidates fairly.')]);
P('unbind','From un- “reverse” + bind, a Germanic verb meaning tie or fasten.',[C('unbind.s1','解开束缚','The rescue workers unbound the prisoner’s wrists after confirming he was safe.','救援人員確認囚犯安全後，解開了他手腕上的綁縛。','unbind + person / hands / fastening','Verb: set free by undoing bonds or release a fastening.','The bindings are undone so the wrists are free.')],[M('The guard unbound the prisoner by tightening the rope around both wrists.','The guard unbound the prisoner by loosening and removing the rope.','To unbind is to undo bonds or release a fastening, not tighten it.')],[Q('unbind.q1','unbind.s1','meaning','What did the rescuers do when they unbound the prisoner?','Undid the bonds holding his wrists.','Tightened the rope more firmly.','Bound his hands together again.','Unbind means release by undoing bonds.'),Q('unbind.q2','unbind.s1','context','How can you unbind a parcel?','Undo the string or fastening around it.','Add another knot to secure it.','Type the address on the parcel.','The verb can mean release a fastening.'),Q('unbind.q3','unbind.s1','distinction','Which action unbinds someone?','Cutting or loosening the cords around their wrists.','Tying their wrists together.','Adding a tighter knot.','Removing the cords releases the person.'),Q('unbind.q4','unbind.s1','word-choice','Choose the accurate phrase.','The nurse unbound the patient’s hands.','The nurse unbound the patient by adding tighter restraints.','The nurse unbound a type of umbrella.','Removing restraints sets the hands free.')]);
P('unblemished','From un- “not” + blemished, from blemish “mark or flaw.”',[C('unblemished.s1','表面','The jeweller chose an unblemished pearl with no visible spots or scratches.','珠寶商挑選了一顆表面沒有斑點或刮痕的無瑕珍珠。','unblemished + skin, surface, or object','Adjective: having no marks, spots, or damage on the surface.','The pearl’s surface is free from visible flaws.'),C('unblemished.s2','记录与声誉','The inspector retired with an unblemished record after decades of honest service.','這名檢查員多年誠實服務後退休，職業紀錄沒有任何污點。','an unblemished record / reputation','Adjective: having a perfect record with no faults or scandals.','No misconduct or scandal mars the inspector’s history.')],[M('The inspector had an unblemished record despite several proven cases of bribery and fraud.','The inspector had an unblemished record with no proven misconduct or scandal.','An unblemished record has no faults or scandals.')],[Q('unblemished.q1','unblemished.s1','meaning','What did an unblemished pearl look like?','It had no visible spots or scratches.','It was covered in damage and marks.','It had a spotless career record.','The surface sense means without marks or damage.'),Q('unblemished.q2','unblemished.s2','context','Why did the inspector retire with an unblemished record?','No fault or scandal marred the inspector’s career.','Several bribery cases had been proved.','The inspector’s skin had no spots.','The figurative sense describes a perfect record.'),Q('unblemished.q3','unblemished.s1','distinction','Which use describes a physical surface?','unblemished skin without spots','an unblemished record of service','an unblemished reputation after a long career','The skin is free from marks.'),Q('unblemished.q4','unblemished.s2','word-choice','Which phrase uses the record sense?','an unblemished safety record over twenty years','an unblemished polished stone','unblemished skin with no marks','The safety record has no faults or scandals.')]);
})();
